// Reviewed histories, EE/LT popular round 1 (Estonian names A): most common EE/LT names by official bearer counts.
// Source URLs are research/provenance metadata only and are never displayed in the widget.
export const historiesEeA={};
function add(names,sources,text){for(const name of names.split('|'))historiesEeA[name]={sources,text};}
add('Margus',['https://et.wikipedia.org/wiki/Margus','https://www.behindthename.com/name/marcus','https://et.wikipedia.org/wiki/Markusep%C3%A4ev','https://en.wikipedia.org/wiki/St_Mark%27s_Basilica'],{
 ru:['Margus — эстонская форма имени Marcus. Это было римское личное имя, которое, вероятно, связано с именем бога войны Марса. В христианском мире его прославил евангелист Марк, автор второго Евангелия. Именины Margus отмечает 25 апреля, в день святого Марка — по-эстонски markusepäev. В народе этот день называли ещё äkksurmapäev, «днём внезапной смерти»: считалось, что если в этот день пахать или работать в поле, скот неожиданно погибнет.','Святой Марк — покровитель Венеции, и его мощи стали предметом одной из самых известных средневековых историй. Хроники рассказывают, что в 828 или 829 году два венецианских купца тайно вывезли тело евангелиста — без головы — из египетской Александрии в Венецию. Эта перевозка изображена на мозаиках над порталами собора Святого Марка. В 1968 году часть мощей вернули Коптской церкви Александрии, и там они снова соединились с главой святого.'],
 en:['Margus is the Estonian form of Marcus, a Roman given name that was probably derived from the name of Mars, the god of war. Christians came to know it through Mark the Evangelist, the author of the second gospel. Margus has its name day on 25 April, St Mark’s day, called markusepäev in Estonian. Folk tradition also knew it as äkksurmapäev, “sudden-death day”: people believed that ploughing or other field work on that day would make the animals die unexpectedly.','St Mark is the patron saint of Venice, and his relics are at the centre of one of the best-known medieval stories. According to the chronicles, two Venetian merchants removed the evangelist’s body, without the head, from Alexandria in Egypt and brought it to Venice in 828 or 829. The mosaics above the portals of St Mark’s Basilica still tell this story. In 1968 part of the relics was returned to the Coptic Church of Alexandria, where it was reunited with the saint’s head.'],
 lv:['Margus ir igauņu vārda Marcus forma. Tas bija romiešu personvārds, kas, visticamāk, atvasināts no kara dieva Marsa vārda. Kristīgajā pasaulē to padarīja slavenu evaņģēlists Marks, otrā evaņģēlija autors. Margus vārda diena ir 25. aprīlī, svētā Marka dienā, ko igauņi sauc par markusepäev. Tautā to sauca arī par äkksurmapäev — «pēkšņās nāves dienu»: ticēja, ka tad, ja šajā dienā ar vai dara citus lauka darbus, lopi negaidīti nobeigsies.','Svētais Marks ir Venēcijas aizbildnis, un ap viņa relikvijām veidojies viens no pazīstamākajiem viduslaiku stāstiem. Hronikas vēsta, ka 828. vai 829. gadā divi Venēcijas tirgotāji aizveda evaņģēlista ķermeni — bez galvas — no Aleksandrijas Ēģiptē uz Venēciju. Šo pārvešanu joprojām attēlo mozaīkas virs Svētā Marka bazilikas portāliem. 1968. gadā daļu relikviju atdeva Aleksandrijas Koptu baznīcai, un tur tās atkal apvienoja ar svētā galvu.'],
 lt:['Margus — estiška vardo Marcus forma. Tai buvo romėnų asmenvardis, greičiausiai kilęs iš karo dievo Marso vardo. Krikščionių pasaulyje jį išgarsino evangelistas Morkus, antrosios Evangelijos autorius. Margus vardadienį švenčia balandžio 25 dieną, šv. Morkaus dieną, estiškai vadinamą markusepäev. Liaudyje ji dar buvo vadinama äkksurmapäev — „staigios mirties diena“: tikėta, kad jei tą dieną arsi ar dirbsi lauke, gyvuliai netikėtai nugaiš.','Šv. Morkus — Venecijos globėjas, o apie jo relikvijas susiklostė viena žinomiausių viduramžių istorijų. Kronikos pasakoja, kad 828 ar 829 metais du Venecijos pirkliai išgabeno evangelisto kūną — be galvos — iš Aleksandrijos Egipte į Veneciją. Šį pervežimą iki šiol vaizduoja mozaikos virš Šv. Morkaus bazilikos portalų. 1968 metais dalis relikvijų buvo grąžinta Aleksandrijos koptų Bažnyčiai ir ten vėl sujungta su šventojo galva.'],
 et:['Margus on Marcuse eesti kuju. Marcus oli Rooma isikunimi, mis tuleneb tõenäoliselt sõjajumal Marsi nimest. Kristlikus maailmas tegi selle kuulsaks evangelist Markus, teise evangeeliumi autor. Marguse nimepäev on 25. aprillil, püha Markuse päeval ehk markusepäeval. Rahvasuus kutsuti seda ka äkksurmapäevaks: usuti, et kui sel päeval künda või muud põllutööd teha, surevad loomad ootamatult.','Püha Markus on Veneetsia kaitsepühak ning tema säilmete ümber on tekkinud üks tuntumaid keskaja lugusid. Kroonikate järgi viisid kaks Veneetsia kaupmeest aastal 828 või 829 evangelisti keha — ilma peata — Egiptuse Aleksandriast Veneetsiasse. Seda teekonda kujutavad tänini Püha Markuse basiilika portaalide kohal olevad mosaiigid. 1968. aastal anti osa säilmetest tagasi Aleksandria kopti kirikule, kus need ühendati taas pühaku peaga.']
});
add('Sirje',['https://www.behindthename.com/name/sirje','https://fi.wikipedia.org/wiki/Sirja','https://et.wikipedia.org/wiki/Sirje','https://et.wikipedia.org/wiki/Tasuleegid'],{
 ru:['Sirje — эстонское женское имя. Возможно, его взяли из слова sinisirje — «синеперая»: так в эстонской народной песне «Sinisirje linnukene» называют птичку, а сходное слово связывают и с волшебной птицей в эпосе «Калевипоэг». Как личное имя Sirje предложил языковед Юлиус Мягисте в 1929 году. Позже имя вошло и в латышский календарь именин.','С именем связывают и оперу Эугена Каппа «Tasuleegid» («Пламя мести»). Либретто Пауля Руммо основано на повести Эдуарда Борнхёэ «Мститель» о восстании Юрьевой ночи. Премьера прошла 21 июля 1945 года в Таллине, в зале кинотеатра «Глория Палас», силами труппы театра «Эстония». Одну из главных партий, сопрановую, пела героиня по имени Сирье. В 1946 году композитор получил за оперу Сталинскую премию.'],
 en:['Sirje is an Estonian women’s name. It possibly comes from sinisirje, “blue-feathered”, the word used for a little bird in the Estonian folk song “Sinisirje linnukene”; a similar word is also connected with a magical bird in the national epic Kalevipoeg. The linguist Julius Mägiste suggested Sirje as a given name in 1929. The name later found a place in the Latvian name-day calendar as well.','The name is also associated with Eugen Kapp’s opera Tasuleegid (“Flames of Vengeance”). Paul Rummo’s libretto was based on Eduard Bornhöhe’s story Tasuja (“The Avenger”) about the St George’s Night Uprising. The opera was first performed on 21 July 1945 in Tallinn, in the Gloria Palace cinema, by the company of the Estonia Theatre, and one of its main soprano roles was a heroine called Sirje. In 1946 the composer received a Stalin Prize for the work.'],
 lv:['Sirje ir igauņu sieviešu vārds. Iespējams, tas ņemts no vārda sinisirje — «zilspalvains»: tā igauņu tautasdziesmā «Sinisirje linnukene» sauc putniņu, bet līdzīgu vārdu saista arī ar burvju putnu eposā «Kalevipoegs». Kā personvārdu Sirje 1929. gadā ieteica valodnieks Jūliuss Mēgiste. Vēlāk vārds iekļuva arī latviešu vārdadienu kalendārā.','Vārdu saista arī ar Eižena Kapa operu «Tasuleegid» («Atriebības liesmas»). Paula Rummo libretu veidoja pēc Eduarda Bornhēes stāsta «Atriebējs» par Jura nakts sacelšanos. Pirmizrāde notika 1945. gada 21. jūlijā Tallinā, kinoteātra «Gloria Palace» zālē, to izrādīja teātra «Estonia» trupa, un vienā no galvenajām soprāna lomām bija varone vārdā Sirje. 1946. gadā komponists par šo darbu saņēma Staļina prēmiju.'],
 lt:['Sirje — estiškas moters vardas. Galbūt jis paimtas iš žodžio sinisirje — „mėlynaplunksnė“: taip estų liaudies dainoje „Sinisirje linnukene“ vadinamas paukštelis, o panašus žodis siejamas ir su stebuklingu paukščiu epe „Kalevipoegas“. Kaip asmenvardį Sirje 1929 metais pasiūlė kalbininkas Juliusas Mägiste. Vėliau vardas pateko ir į latvių vardadienių kalendorių.','Vardas siejamas ir su Eugeno Kappo opera „Tasuleegid“ („Keršto liepsnos“). Paulo Rummo libretas parašytas pagal Eduardo Bornhöhe’s apysaką „Keršytojas“ apie Jurginių nakties sukilimą. Premjera įvyko 1945 metų liepos 21 dieną Taline, kino teatro „Gloria Palace“ salėje, ją parodė teatro „Estonia“ trupė, o viena pagrindinių sopraninių partijų buvo herojė, vardu Sirje. 1946 metais kompozitorius už šį kūrinį gavo Stalino premiją.'],
 et:['Sirje on eesti naisenimi. Võimalik, et see on võetud sõnast sinisirje, millega rahvalaulus „Sinisirje linnukene“ nimetatakse linnukest; sarnast sõna seostatakse ka „Kalevipoja“ võlulinnuga. Eesnimeks soovitas Sirjet keeleteadlane Julius Mägiste 1929. aastal. Hiljem jõudis nimi ka Läti nimepäevakalendrisse.','Nime on seostatud ka Eugen Kapi ooperiga „Tasuleegid“. Paul Rummo libreto põhines Eduard Bornhöhe jüriöö ülestõusu ainelisel jutustusel „Tasuja“. Esietendus toimus 21. juulil 1945 Tallinnas kino Gloria Palace ruumides Estonia teatri trupi esituses ning üks peamisi sopraniosi oli Sirje-nimelisel kangelannal. 1946. aastal sai helilooja ooperi eest Stalini preemia.']
});
add('Kristjan',['https://et.wikipedia.org/wiki/Kristjan','https://www.behindthename.com/name/christian','https://et.wikipedia.org/wiki/Kristjan_Jaak_Peterson'],{
 ru:['Kristjan — эстонская (а также словенская) форма имени Christian. Оно восходит к средневековому латинскому Christianus — «христианин», а через греческое Christos связано с титулом Христа. В Северной Европе имя носили многие правители: начиная с XV века десять королей Дании звались Кристианами.','Самый известный в Эстонии Кристьян — поэт Кристьян Яак Петерсон. Его настоящее имя — Christian Jakob Petersohn; он родился в Риге 14 марта 1801 года в семье звонаря эстонской общины. Петерсон учился богословию в Тарту, называл себя певцом «маарахва», то есть эстонцев, и верил, что возможна самобытная эстонская литература. Он умер от туберкулёза в 21 год, а день его рождения, 14 марта, в Эстонии отмечают как День родного языка.'],
 en:['Kristjan is the Estonian (and also Slovene) form of Christian. It goes back to medieval Latin Christianus, “a Christian”, and through Greek Christos to the title of Christ. Many northern European rulers bore the name: from the fifteenth century onwards ten kings of Denmark were called Christian.','The best-known Kristjan in Estonia is the poet Kristjan Jaak Peterson, originally Christian Jakob Petersohn. He was born in Riga on 14 March 1801, the son of the bell-ringer of the Estonian congregation there. Peterson studied theology in Tartu, called himself a singer of the maarahvas, the Estonian country people, and believed that an original Estonian literature was possible. He died of tuberculosis at the age of 21, and his birthday, 14 March, is celebrated in Estonia as Native Language Day.'],
 lv:['Kristjan ir igauņu (un arī slovēņu) vārda Christian forma. Tas cēlies no viduslaiku latīņu Christianus — «kristietis», bet caur grieķu Christos saistīts ar Kristus titulu. Ziemeļeiropā šo vārdu nesuši daudzi valdnieki: kopš 15. gadsimta desmit Dānijas karaļi sauca par Kristiānu.','Igaunijā pazīstamākais Kristjans ir dzejnieks Kristjans Jāks Petersons, dokumentos — Christian Jakob Petersohn. Viņš dzimis Rīgā 1801. gada 14. martā igauņu draudzes zvaniķa ģimenē. Petersons studēja teoloģiju Tartu, sauca sevi par maarahvas — igauņu zemnieku tautas — dziedoni un ticēja, ka iespējama oriģināla igauņu literatūra. Viņš nomira no tuberkulozes 21 gada vecumā, un viņa dzimšanas diena, 14. marts, Igaunijā tiek svinēta kā Dzimtās valodas diena.'],
 lt:['Kristjan — estiška (taip pat slovėniška) vardo Christian forma. Jis kilęs iš viduramžių lotynų Christianus — „krikščionis“, o per graikų Christos susijęs su Kristaus titulu. Šiaurės Europoje šį vardą nešiojo daug valdovų: nuo XV amžiaus dešimt Danijos karalių vadinosi Kristianais.','Garsiausias Estijos Kristjanas — poetas Kristjanas Jaakas Petersonas, dokumentuose užrašytas kaip Christian Jakob Petersohn. Jis gimė Rygoje 1801 metų kovo 14 dieną estų parapijos varpininko šeimoje. Petersonas studijavo teologiją Tartu, vadino save maarahvas — estų kaimo tautos — dainiumi ir tikėjo, kad įmanoma savita estų literatūra. Jis mirė nuo tuberkuliozės sulaukęs 21 metų, o jo gimimo diena, kovo 14-oji, Estijoje švenčiama kaip Gimtosios kalbos diena.'],
 et:['Kristjan on nime Christian eesti (ja ka sloveeni) kuju. See ulatub keskaegse ladina nimeni Christianus, „kristlane“, ning kreeka sõna Christos kaudu Kristuse tiitlini. Põhja-Euroopas kandsid nime paljud valitsejad: alates 15. sajandist on Taanis olnud kümme Christiani-nimelist kuningat.','Eesti tuntuim Kristjan on luuletaja Kristjan Jaak Peterson, õieti Christian Jakob Petersohn. Ta sündis 14. märtsil 1801 Riias eesti koguduse kellamehe pojana. Peterson õppis Tartu ülikoolis usuteadust, nimetas end maarahva laulikuks ja pidas võimalikuks algupärase eesti kirjanduse loomist. Ta suri tuberkuloosi 21-aastaselt ning tema sünniaastapäeval, 14. märtsil, tähistatakse Eestis emakeelepäeva.']
});
add('Ülle',['https://en.wikipedia.org/wiki/%C3%9Clle','https://www.nordicnames.de/wiki/%C3%9Clle','https://www.emakeeleselts.ee/wp-content/uploads/2021/12/Hergauk-Mald.pdf','https://et.wikipedia.org/wiki/Kauksi_%C3%9Clle'],{
 ru:['Ülle — эстонское женское имя, женская пара мужского имени Ülo. Справочник Nordic Names связывает его с эстонским словом ülev — «возвышенный, благородный». Оба имени принадлежат к волне эстонских имён XX века: 1930-е годы стали временем, когда возрождали древние эстонские имена и охотно давали новые, созвучные родному языку; среди них исследователи называют и Ülo.','Особенно интересно имя звучит у поэтессы из Вырумаа, которая подписывается Kauksi Ülle — фамилия идёт впереди, а по документам она Ülle Kauksi. Она родилась в 1962 году в Выру и пишет стихи, прозу и пьесы на выруском языке. По её словам, стихи она начала писать, ещё не осознавая, что пишет по-выруски; первый сборник «Kesk umma mäke» вышел в 1987 году.'],
 en:['Ülle is an Estonian women’s name, the feminine counterpart of the men’s name Ülo. The Nordic Names reference links it with the Estonian word ülev, “lofty, noble-minded”. Both belong to the wave of twentieth-century Estonian names: the 1930s were the high point of reviving ancient Estonian names and adopting new names that sounded native, and Ülo is one of the names researchers mention from that period.','A memorable bearer is the Võro poet who writes as Kauksi Ülle, with the family name first, while her civil name is Ülle Kauksi. Born in Võru in 1962, she writes poetry, prose and plays in the Võro language of south-eastern Estonia. She began writing poems before she realised that she was writing in Võro, and her first collection, Kesk umma mäke, appeared in 1987.'],
 lv:['Ülle ir igauņu sieviešu vārds, vīriešu vārda Ülo sieviešu pāris. Uzziņu avots Nordic Names to saista ar igauņu vārdu ülev — «cildens, cēls». Abi pieder pie 20. gadsimta igauņu vārdu viļņa: 1930. gadi bija laiks, kad visvairāk atdzīvināja senos igauņu vārdus un deva jaunus, igauniski skanošus vārdus, un pētnieki starp tā laika vārdiem min arī Ülo.','Īpaši interesanti vārds skan võru dzejniecei, kura paraksta darbus kā Kauksi Ülle — ar uzvārdu priekšā, bet dokumentos viņa ir Ülle Kauksi. Viņa dzimusi Võru 1962. gadā un raksta dzeju, prozu un lugas Dienvidaustrumigaunijas võru valodā. Dzejoļus viņa sākusi rakstīt, vēl neapzinoties, ka raksta võru valodā, un pirmais krājums «Kesk umma mäke» iznāca 1987. gadā.'],
 lt:['Ülle — estiškas moters vardas, vyriško vardo Ülo moteriška pora. Žinynas Nordic Names jį sieja su estų žodžiu ülev — „kilnus, didingas“. Abu vardai priklauso XX amžiaus estiškų vardų bangai: XX amžiaus ketvirtasis dešimtmetis buvo senųjų estiškų vardų atgaivinimo ir naujų, estiškai skambančių vardų viršūnė, o tyrėjai tarp to meto vardų mini ir Ülo.','Įdomiai vardas skamba võrų poetės, pasirašančios Kauksi Ülle, atveju: pavardė eina pirma, o dokumentuose ji yra Ülle Kauksi. Ji gimė Võru mieste 1962 metais ir rašo poeziją, prozą bei pjeses pietryčių Estijos võrų kalba. Eilėraščius ji pradėjo rašyti dar nežinodama, kad rašo võrų kalba, o pirmasis rinkinys „Kesk umma mäke“ išėjo 1987 metais.'],
 et:['Ülle on eesti naisenimi, mehenime Ülo naissoost paariline. Nordic Namesi andmestik seostab seda sõnaga ülev. Mõlemad kuuluvad 20. sajandi eesti nimede lainesse: 1930. aastad olid muinaseesti nimede taaselustamise ja uute eestipäraste nimede kõrghetk ning uurijad nimetavad tolle aja nimede seas ka Ülot.','Omanäoliselt kõlab nimi võro luuletaja puhul, kes kirjutab nime all Kauksi Ülle — perekonnanimi ees, kodanikunimega aga on ta Ülle Kauksi. Ta sündis 1962. aastal Võrus ning kirjutab võro keeles luulet, proosat ja näidendeid. Luuletusi hakkas ta kirjutama teadmata, et kirjutab võro keeles; esimene kogu „Kesk umma mäke“ ilmus 1987. aastal.']
});
add('Urmas',['https://www.behindthename.com/name/urmas','https://fi.wikipedia.org/wiki/Urmas','https://en.wikipedia.org/wiki/Johannes_Linnankoski','https://www.gutenberg.org/ebooks/12838'],{
 ru:['Urmas — мужское имя, известное в Финляндии и Эстонии. Его происхождение не установлено. Behind the Name допускает связь с диалектным эстонским словом urm — «иней» или «серёжка» (соцветие ивы, берёзы). Финские источники сообщают, что в Финляндии Urmas сначала был названием хутора в Коски (бывшая губерния Турку) и встречается там также как фамилия. Позже имя распространилось и в Эстонии, где Urmas есть и в местных названиях.','Личным именем Urmas стал благодаря финскому писателю Йоханнесу Линнанкоски (настоящая фамилия — Пелтонен). В начале XX века он какое-то время жил в Коски и назвал Урмасом одного из своих сыновей. То же имя он дал персонажу своей драмы «Kirot» («Проклятия»): в списке действующих лиц Урмас — вождь племени мерви. Так название хутора через семью писателя и литературу превратилось в имя, которое затем подхватили и эстонцы.'],
 en:['Urmas is a men’s name used in Finland and Estonia, and its origin is not settled. Behind the Name suggests a possible link with the dialectal Estonian word urm, “frost” or “catkin”. Finnish sources state that in Finland Urmas was originally the name of a farm at Koski in the former province of Turku, where it also occurs as a surname. The name later came into use in Estonia, where Urmas also appears in place names.','Urmas became a personal name thanks to the Finnish writer Johannes Linnankoski, whose real surname was Peltonen. In the early twentieth century he lived for a time at Koski, and he gave the name Urmas to one of his sons. He also used it for a character in his play Kirot (“Curses”), whose cast list presents Urmas as the leader of the Mervi people. In this way a farm name passed through a writer’s family and a work of literature into a given name that Estonians later adopted as well.'],
 lv:['Urmas ir vīriešu vārds, kas sastopams Somijā un Igaunijā, un tā izcelsme nav noskaidrota. Behind the Name pieļauj saistību ar igauņu dialektu vārdu urm — «sarma» vai «spurdziņa» (kārkla, bērza ziedkopa). Somu avoti vēsta, ka Somijā Urmas sākotnēji bija mājas nosaukums Koski bijušajā Turku guberņā, kur tas sastopams arī kā uzvārds. Vēlāk vārds ienāca Igaunijā, kur Urmas ir arī vietvārdos.','Par personvārdu Urmas kļuva, pateicoties somu rakstniekam Johannesam Linnankoski, kura īstais uzvārds bija Peltonens. 20. gadsimta sākumā viņš kādu laiku dzīvoja Koski un vienam no saviem dēliem deva vārdu Urmas. To pašu vārdu viņš piešķīra tēlam lugā «Kirot» («Lāsti»): personu sarakstā Urmas ir mervu tautas vadonis. Tā mājas nosaukums caur rakstnieka ģimeni un literatūru pārvērtās vārdā, ko vēlāk pārņēma arī igauņi.'],
 lt:['Urmas — vyriškas vardas, vartojamas Suomijoje ir Estijoje, o jo kilmė nėra nustatyta. Behind the Name svarsto galimą ryšį su tarminiu estų žodžiu urm — „šerkšnas“ arba „žirginys“ (gluosnio, beržo žiedynas). Suomių šaltiniai nurodo, kad Suomijoje Urmas iš pradžių buvo sodybos pavadinimas Koskyje, buvusioje Turku gubernijoje, kur jis žinomas ir kaip pavardė. Vėliau vardas paplito Estijoje, kur Urmas yra ir vietovardžiuose.','Asmenvardžiu Urmas tapo suomių rašytojo Johanneso Linnankoskio, kurio tikroji pavardė buvo Peltonen, dėka. XX amžiaus pradžioje jis kurį laiką gyveno Koskyje ir vienam savo sūnų davė Urmo vardą. Tą patį vardą jis suteikė personažui savo pjesėje „Kirot“ („Prakeiksmai“): veikėjų sąraše Urmas — mervių genties vadas. Taip sodybos pavadinimas per rašytojo šeimą ir literatūrą virto vardu, kurį vėliau perėmė ir estai.'],
 et:['Urmas on Soomes ja Eestis kasutatav mehenimi, mille päritolu pole selge. Behind the Name pakub võimalikku seost murdesõnaga urm, „härmatis“ või „urb“. Soome allikate järgi oli Urmas Soomes algselt talunimi Koskis endises Turu läänis, kus see esineb ka perekonnanimena. Hiljem tuli nimi kasutusele ka Eestis, kus Urmas esineb ka kohanimedes.','Eesnimeks sai Urmas soome kirjaniku Johannes Linnankoski, kodanikunimega Peltoneni kaudu. 20. sajandi algul elas ta mõnda aega Koskis ning pani ühele oma pojale nimeks Urmas. Sama nime andis ta tegelasele oma näidendis „Kirot“ („Needused“), mille tegelaste nimestikus on Urmas mervide juht. Nii sai talunimest kirjaniku pere ja kirjanduse kaudu eesnimi, mille hiljem võtsid omaks ka eestlased.']
});
add('Tiiu',['https://et.wikipedia.org/wiki/Tiiu_(eesnimi)','https://www.behindthename.com/name/tiiu','https://www.behindthename.com/name/tiia','https://www.emakeeleselts.ee/wp-content/uploads/2021/12/Hergauk-Mald.pdf'],{
 ru:['Tiiu — эстонское женское имя. Эстонская Википедия выводит его из названия синицы (ср. финское tiainen, эстонское tihane). Behind the Name считает Tiiu вариантом имени Tiia — финской и эстонской краткой формы Доротеи — и допускает, что на него отчасти повлияла старая диалектная форма слова tihane. В эстонском календаре Tiiu и Tiia празднуют именины в один день, 1 ноября.','Любопытный след имени остался в школьных учебниках. Лиина Хергаук и Ингрид Мальд изучили имена в эстонских букварях и учебниках математики. В 1940–1985 годах многие задачники переводили с русского и давали героям имена, привычные эстонским детям. Среди женских имён в них чаще всего встречались Malle, Tiiu, Sirje, Tiina и Reet; в одном учебнике Тийу появляется в задачах десять раз.'],
 en:['Tiiu is an Estonian women’s name. Estonian Wikipedia derives it from the name of the titmouse (compare Finnish tiainen, Estonian tihane). Behind the Name treats Tiiu as a variant of Tiia, a Finnish and Estonian short form of Dorothea, possibly influenced in part by an archaic dialect form of tihane. In the Estonian calendar Tiiu and Tiia share their name day, 1 November.','The name left a curious trace in school books. Liina Hergauk and Ingrid Mald studied the names used in Estonian primers and mathematics textbooks. Between 1940 and 1985 many maths textbooks were translated from Russian, and their characters were given names familiar to Estonian children. Among the women’s names, Malle, Tiiu, Sirje, Tiina and Reet were the most frequent; in one textbook the name Tiiu occurs ten times.'],
 lv:['Tiiu ir igauņu sieviešu vārds. Igauņu Vikipēdija to atvasina no zīlītes nosaukuma (sal. somu tiainen, igauņu tihane). Behind the Name uzskata Tiiu par vārda Tiia variantu — Tiia ir Dorotejas somu un igauņu īsā forma — un pieļauj, ka to daļēji ietekmējusi sena vārda tihane dialekta forma. Igauņu kalendārā Tiiu un Tiia vārda diena ir vienā dienā, 1. novembrī.','Interesantas pēdas vārds atstājis skolas grāmatās. Līna Hergauka un Ingrīda Malda pētīja vārdus igauņu ābecēs un matemātikas mācību grāmatās. No 1940. līdz 1985. gadam daudzas matemātikas grāmatas tulkoja no krievu valodas, un to tēliem deva igauņu bērniem pierastus vārdus. No sieviešu vārdiem visbiežāk parādījās Malle, Tiiu, Sirje, Tiina un Reet; vienā grāmatā vārds Tiiu sastopams desmit reizes.'],
 lt:['Tiiu — estiškas moters vardas. Estiškoji Vikipedija jį kildina iš zylės pavadinimo (plg. suomių tiainen, estų tihane). Behind the Name laiko Tiiu vardo Tiia variantu — Tiia yra suomiška ir estiška trumpoji Dorotėjos forma — ir mano, kad jį iš dalies galėjo paveikti sena tarminė žodžio tihane forma. Estų kalendoriuje Tiiu ir Tiia vardadienį švenčia tą pačią dieną, lapkričio 1-ąją.','Įdomų pėdsaką vardas paliko mokykliniuose vadovėliuose. Liina Hergauk ir Ingrid Mald tyrė vardus estų elementoriuose ir matematikos vadovėliuose. 1940–1985 metais daug matematikos vadovėlių buvo verčiama iš rusų kalbos, o jų veikėjams duodami estų vaikams įprasti vardai. Iš moterų vardų dažniausiai pasitaikė Malle, Tiiu, Sirje, Tiina ir Reet; viename vadovėlyje vardas Tiiu pavartotas net dešimt kartų.'],
 et:['Tiiu on eesti naisenimi. Eesti Vikipeedia järgi pärineb see tihase nimest (vrd soome tiainen). Behind the Name peab Tiiut nime Tiia variandiks — Tiia on Dorothea soome ja eesti lühivorm — ning arvab, et seda võis osaliselt mõjutada sõna tihane vana murdekuju. Eesti kalendris on Tiiul ja Tiial ühine nimepäev, 1. november.','Huvitava jälje on nimi jätnud kooliõpikutesse. Liina Hergauk ja Ingrid Mald uurisid eesti aabitsate ja matemaatikaõpikute nimesid. Aastatel 1940–1985 tõlgiti paljud matemaatikaõpikud vene keelest ning tegelased said eesti oludele kohandatud nimed. Naisenimedest olid kõige tavalisemad Malle, Tiiu, Sirje, Tiina ja Reet; ühes õpikus esineb nimi Tiiu koguni kümme korda.']
});
add('Rein',['https://www.behindthename.com/name/rein','https://www.behindthename.com/name/reynold','https://www.emakeeleselts.ee/wp-content/uploads/2021/12/Hergauk-Mald.pdf'],{
 ru:['Rein — мужское имя, которое встречается у фризов, нидерландцев и эстонцев. Изначально это краткая форма древнегерманских имён, начинавшихся с элемента regin — «совет, решение»; тот же элемент есть и в полном имени Reinhold. Эстонский календарь объединяет Rein с Reinhold, Reino, Reinu и Reinut и отмечает их именины в один день — 16 июля.','Имя хорошо знакомо нескольким поколениям эстонских школьников. Исследование Лиины Хергаук и Ингрид Мальд об именах в учебниках показало, что в эстонских букварях 1940–1985 годов самыми частыми мужскими именами были Tõnu и Rein; за ними шли Tiit, Ants, Villu, Enn и Alo. Авторы отмечают, что буквари того времени рисовали радостную картину жизни, где важное место занимали труд, семья и праздники.'],
 en:['Rein is a men’s name used among the Frisians, the Dutch and the Estonians. It began as a short form of old Germanic names beginning with the element regin, “advice, counsel, decision”, the same element found in the fuller name Reinhold. The Estonian calendar groups Rein with Reinhold, Reino, Reinu and Reinut and gives them a shared name day on 16 July.','Several generations of Estonian schoolchildren met the name in their first reading books. In their study of names in school books, Liina Hergauk and Ingrid Mald found that Tõnu and Rein were the most frequent men’s names in Estonian primers from 1940 to 1985, followed by Tiit, Ants, Villu, Enn and Alo. The authors note that primers of that period painted a cheerful picture of life in which work, family and holidays held an important place.'],
 lv:['Rein ir vīriešu vārds, kas sastopams frīziem, nīderlandiešiem un igauņiem. Sākotnēji tā ir īsā forma senģermāņu vārdiem, kas sākās ar elementu regin — «padoms, lēmums»; tas pats elements ir arī pilnajā vārdā Reinhold. Igauņu kalendārā Rein apvienots ar Reinhold, Reino, Reinu un Reinut, un to kopīgā vārda diena ir 16. jūlijā.','Vārdu labi pazīst vairākas igauņu skolēnu paaudzes. Līnas Hergaukas un Ingrīdas Maldas pētījums par vārdiem mācību grāmatās parādīja, ka igauņu ābecēs no 1940. līdz 1985. gadam biežākie vīriešu vārdi bija Tõnu un Rein, kam sekoja Tiit, Ants, Villu, Enn un Alo. Autores norāda, ka tā laika ābecēs bija attēlota priecīga dzīve, kurā svarīga vieta bija darbam, ģimenei un svētkiem.'],
 lt:['Rein — vyriškas vardas, vartojamas fryzų, olandų ir estų. Iš pradžių tai buvo trumpoji senųjų germanų vardų, prasidedančių dėmeniu regin — „patarimas, sprendimas“, forma; tas pats dėmuo yra ir pilname varde Reinhold. Estų kalendorius Rein jungia su Reinhold, Reino, Reinu ir Reinut ir jų bendrą vardadienį mini liepos 16 dieną.','Vardą gerai pažįsta kelios estų moksleivių kartos. Liinos Hergauk ir Ingrid Mald tyrimas apie vardus vadovėliuose parodė, kad 1940–1985 metų estų elementoriuose dažniausi vyrų vardai buvo Tõnu ir Rein, po jų ėjo Tiit, Ants, Villu, Enn ir Alo. Autorės pažymi, kad to meto elementoriuose buvo piešiamas džiugus gyvenimo vaizdas, kuriame svarbią vietą užėmė darbas, šeima ir šventės.'],
 et:['Rein on mehenimi, mida kasutavad friisid, hollandlased ja eestlased. Algselt oli see lühivorm vanadest germaani nimedest, mis algasid osaga regin, „nõu, otsus“; sama osa on ka täisnimes Reinhold. Eesti kalender ühendab Reinu Reinholdi, Reino, Reinu ja Reinutiga ning neil on ühine nimepäev 16. juulil.','Nimi on tuttav mitmele põlvkonnale eesti koolilastele. Liina Hergauki ja Ingrid Maldi uurimus õpikute nimedest näitas, et aastatel 1940–1985 olid eesti aabitsates kõige sagedasemad mehenimed Tõnu ja Rein, neile järgnesid Tiit, Ants, Villu, Enn ja Alo. Autorid märgivad, et tolle aja aabitsad maalisid rõõmsa eluolu pildi, kus tähtsal kohal olid töö, pere ja tähtpäevad.']
});
add('Ene',['https://et.wikipedia.org/wiki/Ene_(eesnimi)','https://www.behindthename.com/name/ene','https://www.emakeeleselts.ee/wp-content/uploads/2021/12/Hergauk-Mald.pdf'],{
 ru:['Ene — женское имя, хорошо известное в Эстонии; есть оно и в латышском календаре именин. Его основа точно не установлена. Behind the Name допускает, что это форма имён Anu, Anne или Henrika, а эстонская справочная статья подчёркивает, что имеющиеся данные пока не позволяют сказать ничего окончательного о том, от какого имени произошло Ene.','У имени длинная документальная история. В старых эстонских грамотах оно встречается в формах Ene и Hene, а в церковных книгах XVIII–XIX веков — как Eno и Enu. В современный обиход имя вернулось как литературное и прочно вошло в школьные книги: исследование Лиины Хергаук и Ингрид Мальд показало, что Ene было среди частых женских имён букварей 1940–1985 годов, а в букварях 2010–2020 годов самыми частыми женскими именами были Mari, Ene, Mai и Ann.'],
 en:['Ene is a women’s name well known in Estonia, and it also appears in the Latvian name-day calendar. Its base has not been established. Behind the Name suggests that it may be a form of Anu, Anne or Henrika, while the Estonian reference article stresses that the available evidence does not yet allow anything definite to be said about the name Ene developed from.','The name has a long documentary history. Older Estonian charters record it as Ene and Hene, while eighteenth- and nineteenth-century church registers have the forms Eno and Enu. It returned to modern use as a literary name and settled firmly into school books: a study by Liina Hergauk and Ingrid Mald found Ene among the frequent women’s names in primers of 1940–1985, and in primers published between 2010 and 2020 the most frequent women’s names were Mari, Ene, Mai and Ann.'],
 lv:['Ene ir sieviešu vārds, labi pazīstams Igaunijā, un tas ir arī latviešu vārdadienu kalendārā. Tā pamats nav noskaidrots. Behind the Name pieļauj, ka tā ir vārdu Anu, Anne vai Henrika forma, bet igauņu uzziņu raksts uzsver, ka pieejamie dati pagaidām neļauj neko galīgi apgalvot par to, no kāda vārda Ene cēlies.','Vārdam ir gara dokumentāla vēsture. Vecākos igauņu dokumentos tas sastopams kā Ene un Hene, bet 18. un 19. gadsimta baznīcas grāmatās — kā Eno un Enu. Mūsdienu lietojumā vārds atgriezās kā literārs vārds un stingri iegāja skolas grāmatās: Līnas Hergaukas un Ingrīdas Maldas pētījums parādīja, ka Ene bija starp biežajiem sieviešu vārdiem 1940.–1985. gada ābecēs, bet 2010.–2020. gada ābecēs biežākie sieviešu vārdi bija Mari, Ene, Mai un Ann.'],
 lt:['Ene — gerai Estijoje žinomas moters vardas, jis yra ir latvių vardadienių kalendoriuje. Jo pagrindas nenustatytas. Behind the Name svarsto, kad tai gali būti vardų Anu, Anne ar Henrika forma, o estų žinyno straipsnis pabrėžia, kad turimi duomenys kol kas neleidžia nieko galutinai teigti, iš kokio vardo kilo Ene.','Vardas turi ilgą dokumentinę istoriją. Senesniuose estų dokumentuose jis užrašytas kaip Ene ir Hene, o XVIII–XIX amžiaus bažnytinėse knygose — kaip Eno ir Enu. Į dabartinę vartoseną vardas grįžo kaip literatūrinis ir tvirtai įsitvirtino mokyklinėse knygose: Liinos Hergauk ir Ingrid Mald tyrimas parodė, kad Ene buvo tarp dažnų moterų vardų 1940–1985 metų elementoriuose, o 2010–2020 metų elementoriuose dažniausi moterų vardai buvo Mari, Ene, Mai ir Ann.'],
 et:['Ene on Eestis hästi tuntud naisenimi, mis on ka Läti nimepäevakalendris. Selle alusnimi pole teada. Behind the Name arvab, et see võib olla nimede Anu, Anne või Henrika kuju, eesti allikas aga rõhutab, et andmed ei võimalda praegu Ene alusnime kohta midagi lõplikku väita.','Nimel on pikk dokumenteeritud ajalugu. Varasemates ürikutes esineb see Ene ja Hene kujul, 18. ja 19. sajandi kirikuraamatutes aga Eno ja Enu kujul. Praegusesse pruuki tuli nimi kirjandusliku nimena ning kinnistus ka kooliraamatutes: Liina Hergauki ja Ingrid Maldi uurimus näitas, et Ene oli sagedaste naisenimede seas aastate 1940–1985 aabitsates ning aastatel 2010–2020 ilmunud aabitsate sagedasemad naisenimed olid Mari, Ene, Mai ja Ann.']
});
add('Piret',['https://www.behindthename.com/name/piret','https://www.behindthename.com/name/bridget','https://en.wikipedia.org/wiki/Brigid_of_Kildare','https://et.wikipedia.org/wiki/Suur_T%C3%B5ll'],{
 ru:['Piret — эстонская форма имени Биргитта. Биргитта, скорее всего, скандинавский вариант имени Бригитта, восходящего к ирландскому Brighid (древнеирл. Brigit), от кельтского *Brigantī — «возвышенная». В Скандинавии имя прославила святая Биргитта Шведская, основательница ордена бригитток в XIV веке. Эстонские именины Piret приходятся на 1 февраля — день святой Бригитты Кильдэрской, ирландской святой, чей праздник совпадает с древним праздником начала весны Имболк.','В эстонском фольклоре Пирет — жена великана Суур Тылля, богатыря с острова Сааремаа. Предания рассказывают, что Тылль защищал свой народ от врагов, любил есть капусту и одним шагом перешагивал весь остров; у него были жена Пирет, брат Лейгер на Хийумаа и сын Ноор Тылль. Все предания о Тылле, собранные до 1961 года, издали в 1963 году, а в 1980 году по ним вышел мультфильм «Суур Тылль» режиссёра Рейна Раамата с художником Юри Арраком.'],
 en:['Piret is the Estonian form of Birgitta. Birgitta is most likely a Scandinavian form of Bridget, which goes back to Irish Brighid (Old Irish Brigit), from Celtic *Brigantī, “the exalted one”. In Scandinavia the name was made popular by the fourteenth-century Saint Birgitta of Sweden, founder of the Bridgettine order. Piret has its Estonian name day on 1 February, the feast of Saint Brigid of Kildare, the Irish saint whose day coincides with the old Gaelic festival of Imbolc that marked the beginning of spring.','In Estonian folklore Piret is the wife of Suur Tõll, the giant hero of Saaremaa. The legends say that Tõll defended his people against enemies, loved to eat cabbage and could cross the whole island in a single stride; he had a wife, Piret, a brother, Leiger, on Hiiumaa, and a son, Noor Tõll. All the Tõll legends collected up to 1961 were published in 1963, and in 1980 they inspired the animated film Suur Tõll, directed by Rein Raamat with Jüri Arrak as chief artist.'],
 lv:['Piret ir igauņu vārda Birgita forma. Birgita, visticamāk, ir skandināvu vārda Brigita forma, kas cēlusies no īru Brighid (senīru Brigit), no ķeltu *Brigantī — «cildenā». Skandināvijā vārdu padarīja populāru svētā Birgita no Zviedrijas, 14. gadsimta Birgitīņu ordeņa dibinātāja. Piret vārda diena Igaunijā ir 1. februārī — Kildēras svētās Brigitas dienā; šīs īru svētās diena sakrīt ar seno ģēlu svētku Imbolku, kas iezīmēja pavasara sākumu.','Igauņu folklorā Pirete ir Sāremas milža varoņa Lielā Tella (Suur Tõll) sieva. Teikas vēsta, ka Tells aizstāvēja savu tautu pret ienaidniekiem, labprāt ēda kāpostus un ar vienu soli pārkāpa visai salai; viņam bija sieva Pirete, brālis Leigers Hījumā un dēls Jaunais Tells. Visas līdz 1961. gadam savāktās teikas par Tellu izdeva 1963. gadā, bet 1980. gadā pēc tām tapa animācijas filma «Suur Tõll», kuras režisors bija Reins Rāmats un galvenais mākslinieks Jiri Arraks.'],
 lt:['Piret — estiška vardo Birgita forma. Birgita greičiausiai yra skandinaviška vardo Brigita forma, kilusi iš airių Brighid (senovės airių Brigit), iš keltų *Brigantī — „iškilioji“. Skandinavijoje vardą išpopuliarino XIV amžiaus šventoji Birgita Švedė, brigitiečių ordino įkūrėja. Estijoje Piret vardadienis yra vasario 1 dieną — šv. Brigitos iš Kildero, airių šventosios, šventė; ji sutampa su senąja gėlų Imbolko švente, žyminčia pavasario pradžią.','Estų tautosakoje Piret — Saremos milžino didvyrio Didžiojo Tiolio (Suur Tõll) žmona. Padavimai pasakoja, kad Tõllis gynė savo žmones nuo priešų, mėgo valgyti kopūstus ir vienu žingsniu peržengdavo visą salą; jis turėjo žmoną Piret, brolį Leigerį Hiiumaa saloje ir sūnų Noor Tõllį. Visi iki 1961 metų surinkti padavimai apie Tõllį buvo išleisti 1963 metais, o 1980 metais pagal juos sukurtas animacinis filmas „Suur Tõll“, kurį režisavo Reinas Raamatas, o vyriausiasis dailininkas buvo Jüri Arrakas.'],
 et:['Piret on Birgitta eesti kuju. Birgitta on tõenäoliselt Brigitta skandinaavia vorm, mis ulatub iiri nimeni Brighid (vanairi Brigit) ja keldi sõnani *Brigantī, „ülev“. Skandinaavias tegi nime populaarseks 14. sajandi püha Birgitta Rootsist, birgitiinide ordu rajaja. Pireti nimepäev Eestis on 1. veebruaril, Kildare’i püha Brigida päeval; selle iiri pühaku päev langeb kokku vana gaeli kevadealguse pühaga Imbolc.','Eesti pärimuses on Piret Saaremaa vägilase Suure Tõllu naine. Muistendite järgi kaitses Tõll oma rahvast vaenlaste eest, armastas süüa palju kapsaid ja kõndis ühe sammuga üle terve Saaremaa; tal olid naine Piret, vend Leiger Hiiumaal ja poeg Noor Tõll. Kõik 1961. aastani kogutud Tõllu-muistendid ilmusid 1963. aastal ning 1980. aastal valmis nende ainetel animafilm „Suur Tõll“, mille lavastas Rein Raamat ja mille peakunstnik oli Jüri Arrak.']
});
add('Priit',['https://www.behindthename.com/name/priit','https://www.behindthename.com/name/frederick','https://en.wikipedia.org/wiki/Priit_P%C3%A4rn'],{
 ru:['Priit — краткая форма имени Priidik, эстонского варианта имени Фридрих. Его древнегерманская основа означает «мирный правитель»: она сложена из слов fridu — «мир» и rih — «правитель, король». Имя веками было распространено в немецкоязычных землях, его носили императоры Священной Римской империи, в том числе Фридрих I Барбаросса, и прусский король Фридрих Великий. В эстонском календаре Priit отмечает именины 5 сентября вместе с Priidik, Priido и Priidu.','Одним из самых известных носителей имени стал художник-мультипликатор Прийт Пярн, родившийся в Таллине в 1946 году. Сначала он работал экологом растений, а в анимацию пришёл, когда принял предложение режиссёра Рейна Раамата сделать рисунки для фильма «Kilplased» (1974). Свой первый фильм «Круглая ли Земля?» он снял в 1977 году. Его чёрный юмор и узнаваемая графика резко отличались и от серьёзных назидательных фильмов Раамата, и от диснеевской манеры «Союзмультфильма».'],
 en:['Priit is a short form of Priidik, the Estonian form of Frederick. Its old Germanic source means “peaceful ruler”, from fridu, “peace”, and rih, “ruler, king”. The name was common for centuries in German-speaking lands and was borne by Holy Roman emperors, among them Frederick I Barbarossa, and by Frederick the Great of Prussia. In the Estonian calendar Priit has its name day on 5 September together with Priidik, Priido and Priidu.','One of the best-known bearers is the animator Priit Pärn, born in Tallinn in 1946. He first worked as a plant ecologist and came to animation when he accepted Rein Raamat’s proposal to make the designs for Kilplased (1974). He directed his first film, Is the Earth Round?, in 1977. His black humour and distinctive graphic style broke away both from Raamat’s serious, moralising films and from the Disney-like manner encouraged by Soyuzmultfilm.'],
 lv:['Priit ir vārda Priidik īsā forma; Priidik ir igauņu Frīdriha forma. Tā senģermāņu pamats nozīmē «miermīlīgs valdnieks» un salikts no fridu — «miers» un rih — «valdnieks, karalis». Vācu zemēs vārds bija izplatīts gadsimtiem ilgi, to nesa Svētās Romas impērijas imperatori, arī Frīdrihs I Barbarosa, un Prūsijas karalis Frīdrihs Lielais. Igauņu kalendārā Priit vārda diena ir 5. septembrī kopā ar Priidik, Priido un Priidu.','Viens no pazīstamākajiem šī vārda nesējiem ir animācijas mākslinieks Prīts Pērns, dzimis Tallinā 1946. gadā. Sākumā viņš strādāja par augu ekologu, bet animācijā nonāca, pieņemot režisora Reina Rāmata piedāvājumu veidot zīmējumus filmai «Kilplased» (1974). Savu pirmo filmu «Vai Zeme ir apaļa?» viņš uzņēma 1977. gadā. Viņa melnais humors un savdabīgā grafika krasi atšķīrās gan no Rāmata nopietnajām, pamācošajām filmām, gan no «Sojuzmuļtfiļm» diznejiskās manieres.'],
 lt:['Priit — vardo Priidik trumpinys, o Priidik yra estiška Frydricho forma. Jo senasis germaniškas pagrindas reiškia „taikus valdovas“: jis sudarytas iš fridu — „taika“ ir rih — „valdovas, karalius“. Vokiškai kalbančiuose kraštuose vardas buvo paplitęs šimtmečius, jį nešiojo Šventosios Romos imperijos imperatoriai, tarp jų Frydrichas I Barbarossa, ir Prūsijos karalius Frydrichas Didysis. Estų kalendoriuje Priit vardadienį švenčia rugsėjo 5 dieną kartu su Priidik, Priido ir Priidu.','Vienas žinomiausių šio vardo nešiotojų — animatorius Priitas Pärnas, gimęs Taline 1946 metais. Iš pradžių jis dirbo augalų ekologu, o į animaciją atėjo priėmęs režisieriaus Reino Raamato pasiūlymą piešti filmui „Kilplased“ (1974). Pirmąjį savo filmą „Ar Žemė apvali?“ jis sukūrė 1977 metais. Jo juodasis humoras ir savitas grafinis stilius ryškiai skyrėsi ir nuo rimtų, pamokančių Raamato filmų, ir nuo „Sojuzmultfilm“ puoselėtos disneriškos manieros.'],
 et:['Priit on nime Priidik lühivorm; Priidik on Friedrichi eesti kuju. Selle vana germaani alus tähendab „rahumeelset valitsejat“ ja koosneb sõnadest fridu, „rahu“, ning rih, „valitseja, kuningas“. Saksa keelealal oli nimi levinud sajandeid, seda kandsid Saksa-Rooma keisrid, nende seas Friedrich I Barbarossa, ning Preisi kuningas Friedrich Suur. Eesti kalendris on Priidul nimepäev 5. septembril koos Priidiku, Priido ja Priiduga.','Üks tuntumaid nime kandjaid on 1946. aastal Tallinnas sündinud animaator Priit Pärn. Algul töötas ta taimeökoloogina ning jõudis animatsiooni, kui võttis vastu Rein Raamatu ettepaneku teha kujundus filmile „Kilplased“ (1974). Oma esimese filmi „Kas maakera on ümmargune?“ lavastas ta 1977. aastal. Tema must huumor ja omanäoline graafika erinesid selgelt nii Raamatu tõsistest ja moraliseerivatest filmidest kui ka Sojuzmultfilmi disneylikust laadist.']
});
add('Anneli',['https://fi.wikipedia.org/wiki/Anneli','https://www.behindthename.com/name/annelie','https://fi.wikipedia.org/wiki/Anna_(nimi)'],{
 ru:['Anneli — финская, эстонская и шведская форма имени Annelie, которое в немецком языке служит уменьшительной формой имени Анна или сокращением имени Аннелизе. Финские справочники объясняют Anneli либо как ласковую форму Анны, либо как сокращение двойных имён — в Швеции, например, Anne-Louise, а в Эстонии Anneliese. В Эстонии его пишут иногда и как Anne-Ly.','У Аннели два разных именинных дня, и за каждым стоит своя история. В Эстонии Anneli празднует 26 июля вместе с Anne — в день святой Анны, который католики отмечают именно в этот день. В Финляндии Anneli вместе с Anna, Anne, Anni, Anu, Annikki, Annika и Annukka празднует 9 декабря. Анна попала в финский альманах в 1705 году с именинами 15 декабря, а в 1708 году день перенесли на 9 декабря по шведскому образцу.'],
 en:['Anneli is the Finnish, Estonian and Swedish form of Annelie, which in German is a diminutive of Anna or a short form of Anneliese. Finnish references explain Anneli either as a pet form of Anna or as a contraction of double names, such as Anne-Louise in Sweden or Anneliese in Estonia. In Estonia it is sometimes also written Anne-Ly.','Anneli has two different name days, each with its own history. In Estonia it is celebrated on 26 July together with Anne, the day on which Roman Catholics honour Saint Anne. In Finland Anneli shares 9 December with Anna, Anne, Anni, Anu, Annikki, Annika and Annukka. Anna entered the Finnish almanac in 1705 with a name day on 15 December, and in 1708 the day was moved to 9 December, following the Swedish model.'],
 lv:['Anneli ir somu, igauņu un zviedru vārda Annelie forma; vācu valodā Annelie ir Annas deminutīvs vai vārda Anneliese īsā forma. Somu uzziņu avoti skaidro Anneli vai nu kā Annas mīlināmo formu, vai kā salikto vārdu saīsinājumu — Zviedrijā, piemēram, no Anne-Louise, bet Igaunijā no Anneliese. Igaunijā to dažkārt raksta arī kā Anne-Ly.','Anneli ir divas dažādas vārda dienas, un katrai ir savs stāsts. Igaunijā to svin 26. jūlijā kopā ar Anne — dienā, kad Romas katoļi godina svēto Annu. Somijā Anneli kopā ar Anna, Anne, Anni, Anu, Annikki, Annika un Annukka svin 9. decembrī. Anna tika iekļauta somu almanahā 1705. gadā ar vārda dienu 15. decembrī, bet 1708. gadā to pēc zviedru parauga pārcēla uz 9. decembri.'],
 lt:['Anneli — suomiška, estiška ir švediška vardo Annelie forma; vokiečių kalboje Annelie yra Onos (Anna) mažybinė forma arba vardo Anneliese trumpinys. Suomių žinynai Anneli aiškina arba kaip meilią Anos formą, arba kaip dvigubų vardų sutrumpinimą — Švedijoje, pavyzdžiui, iš Anne-Louise, o Estijoje iš Anneliese. Estijoje jis kartais rašomas ir Anne-Ly.','Anneli turi du skirtingus vardadienius, ir kiekvienas jų turi savo istoriją. Estijoje jis švenčiamas liepos 26 dieną kartu su Anne — tą dieną Romos katalikai mini šv. Oną. Suomijoje Anneli kartu su Anna, Anne, Anni, Anu, Annikki, Annika ir Annukka švenčia gruodžio 9-ąją. Anna į suomių almanachą pateko 1705 metais su vardadieniu gruodžio 15-ąją, o 1708 metais diena pagal švedišką pavyzdį perkelta į gruodžio 9-ąją.'],
 et:['Anneli on nime Annelie soome, eesti ja rootsi kuju; saksa keeles on Annelie Anna deminutiiv või nime Anneliese lühivorm. Soome käsiraamatud seletavad Annelit kas Anna hellitusvormina või liitnimede lühenemisena — Rootsis näiteks nimest Anne-Louise, Eestis nimest Anneliese. Eestis kirjutatakse seda vahel ka Anne-Ly.','Annelil on kaks eri nimepäeva ja kummalgi oma lugu. Eestis peetakse seda 26. juulil koos Annega, päeval, mil roomakatoliiklased austavad püha Annat. Soomes on Annelil koos Anna, Anne, Anni, Anu, Annikki, Annika ja Annukkaga nimepäev 9. detsembril. Anna võeti Soome almanahhi 1705. aastal nimepäevaga 15. detsembril ning 1708. aastal viidi päev Rootsi eeskujul 9. detsembrile.']
});
add('Riina',['https://www.behindthename.com/name/riina','https://www.behindthename.com/name/katherine','https://en.wikipedia.org/wiki/Kadriorg_Palace','https://et.wikipedia.org/wiki/Kadrioru_loss'],{
 ru:['Riina — краткая форма эстонского имени Katariina, то есть Екатерина. Греческое Aikaterine толкуют по-разному: его связывали с именем Гекатерина и словом «каждый из двух», с богиней Гекатой, со словом «мука» и даже с коптским именем. В раннехристианское время его сблизили с греческим katharos — «чистый», и латинское написание изменили на Katharina. В эстонском календаре Riin, Riina и Riine празднуют именины в один день — 9 октября.','Самая известная Екатерина в истории Таллина дала имя целому району. После взятия Ревеля в 1710 году Пётр I купил для своей жены Екатерины небольшую мызу у Ласнамяэ, а в июле 1718 года началось строительство нового дворца по проекту Никколо Микетти. Пётр умер в 1725 году, так и не увидев дворец законченным, а Екатерина больше не интересовалась приморской резиденцией. Название Katharinenthal, по-эстонски Kadriorg — «Екатеринина долина», закрепилось за местом лишь в 1740-х годах.'],
 en:['Riina is a short form of the Estonian name Katariina, Katherine. The origin of Greek Aikaterine is debated: it has been linked with an earlier name Hekaterine and the word for “each of the two”, with the goddess Hecate, with the word for “torture” and even with a Coptic name. In the early Christian era it became associated with Greek katharos, “pure”, and the Latin spelling was changed to Katharina. In the Estonian calendar Riin, Riina and Riine share a name day, 9 October.','The most famous Katherine in Tallinn’s history gave her name to a whole district. After the capture of Reval in 1710, Peter the Great bought a small manor at Lasnamäe for his wife Catherine, and in July 1718 work began on a new palace designed by Niccolò Michetti. Peter died in 1725 without seeing it finished, and Catherine took no further interest in the seaside residence. The name Katharinenthal, in Estonian Kadriorg, “Catherine’s valley”, replaced the older place name only in the 1740s.'],
 lv:['Riina ir igauņu vārda Katariina, tas ir, Katrīnas, īsā forma. Grieķu Aikaterine izcelsmi skaidro dažādi: to saista ar agrāko vārdu Hekaterine un vārdu «katrs no diviem», ar dievieti Hekati, ar vārdu «moka» un pat ar kādu koptu vārdu. Agrīnajā kristietībā to sāka saistīt ar grieķu katharos — «tīrs», un latīņu rakstību mainīja uz Katharina. Igauņu kalendārā Riin, Riina un Riine vārda diena ir vienā dienā, 9. oktobrī.','Slavenākā Katrīna Tallinas vēsturē devusi vārdu veselai pilsētas daļai. Pēc Rēveles ieņemšanas 1710. gadā Pēteris I nopirka savai sievai Katrīnai nelielu muižiņu pie Lasnamē, bet 1718. gada jūlijā sākās jaunās pils celtniecība pēc Nikolo Miketi projekta. Pēteris nomira 1725. gadā, nesagaidījis pils pabeigšanu, un Katrīna par piejūras rezidenci vairs neinteresējās. Nosaukums Katharinenthal, igauniski Kadriorg — «Katrīnas ieleja», vecākā vietvārda vietā nostiprinājās tikai 1740. gados.'],
 lt:['Riina — estiško vardo Katariina, t. y. Kotrynos, trumpinys. Graikiško Aikaterine kilmė aiškinama įvairiai: jis siejamas su ankstesniu vardu Hekaterine ir žodžiu „kiekvienas iš dviejų“, su deive Hekate, su žodžiu „kankynė“ ir net su koptišku vardu. Ankstyvaisiais krikščionybės laikais jis imtas sieti su graikų katharos — „tyras“, o lotyniška rašyba pakeista į Katharina. Estų kalendoriuje Riin, Riina ir Riine vardadienį švenčia tą pačią dieną, spalio 9-ąją.','Garsiausia Kotryna Talino istorijoje davė vardą visam miesto rajonui. Po Revelio užėmimo 1710 metais Petras I nupirko savo žmonai Jekaterinai nedidelį dvarelį prie Lasnamės, o 1718 metų liepą pradėti statyti nauji rūmai pagal Niccolò Michetti projektą. Petras mirė 1725 metais nesulaukęs rūmų pabaigos, o Jekaterina pajūrio rezidencija nebesidomėjo. Pavadinimas Katharinenthal, estiškai Kadriorg — „Kotrynos slėnis“, senesnį vietovardį pakeitė tik XVIII amžiaus penktajame dešimtmetyje.'],
 et:['Riina on nime Katariina lühivorm. Kreeka nime Aikaterine päritolu üle vaieldakse: seda on seostatud varasema nimega Hekaterine ja sõnaga „kumbki kahest“, jumalanna Hekatega, sõnaga „piin“ ja isegi kopti nimega. Varakristlikul ajal hakati seda seostama kreeka sõnaga katharos, „puhas“, ning ladinakeelne kirjapilt muudeti kujule Katharina. Eesti kalendris on Riinil, Riinal ja Riinel ühine nimepäev, 9. oktoober.','Tallinna ajaloo kuulsaim Katariina on andnud nime tervele linnaosale. Pärast Tallinna vallutamist 1710. aastal ostis Peeter I oma naisele Katariinale Lasnamäe alla väikese mõisa ning 1718. aasta juulis algas uue lossi ehitus Niccolò Michetti kavandi järgi. Peeter suri 1725. aastal lossi valmimist nägemata ning Katariina mereäärse residentsi vastu enam huvi ei tundnud. Nimi Katharinenthal ehk Kadriorg võeti senise Fonnenthali asemel kasutusele alles 1740. aastatel.']
});
add('Kristi',['https://www.behindthename.com/name/kristi','https://et.wikipedia.org/wiki/Kristi','https://www.behindthename.com/name/christina','https://en.wikipedia.org/wiki/Christina_of_Bolsena'],{
 ru:['Kristi — уменьшительная форма имени Кристина: в английском она образована от Christina или Christine, в эстонском — от Kristiina. Само имя Кристина восходит к латинскому Christiana, женской форме от Christianus — «христианин». В Эстонии Kristi считается эстонской по звучанию формой имени. Свои именины оно празднует 24 июля вместе с Kristiina, Krista, Kristin, Kristel, Kersti и другими формами этого семейства.','Ранние святые с этим именем известны больше по легендам, чем по документам, но у Кристины Больсенской есть и археологический след. В катакомбах у Больсены, в центральной Италии, нашли остатки раннехристианской церкви и гробницу мученицы; надписи показывают, что её звали примерно «Christina» и почитали как святую уже к концу IV века. Святая Кристина в мученическом венце есть и среди дев на мозаике VI века в базилике Сант-Аполлинаре-Нуово в Равенне.'],
 en:['Kristi is a diminutive of Christina: in English it comes from Christina or Christine, in Estonian from Kristiina. Christina itself goes back to Latin Christiana, the feminine of Christianus, “a Christian”. In Estonia Kristi is regarded as a native-sounding form of the name. It celebrates its name day on 24 July together with Kristiina, Krista, Kristin, Kristel, Kersti and other members of the family.','Early saints of this name are known more from legend than from records, but Christina of Bolsena has left an archaeological trace. In catacombs at Bolsena in central Italy, excavators found the remains of an early Christian church and the tomb of a female martyr; inscriptions show that she had a name like “Christina” and was already venerated as a saint by the end of the fourth century. A saint named Christina, wearing a martyr’s crown, also appears in the procession of virgins in a sixth-century mosaic in the Basilica of Sant’Apollinare Nuovo in Ravenna.'],
 lv:['Kristi ir Kristīnas deminutīvs: angļu valodā tas veidots no Christina vai Christine, igauņu valodā — no Kristiina. Pats vārds Kristīna cēlies no latīņu Christiana, vārda Christianus — «kristietis» — sieviešu formas. Igaunijā Kristi uzskata par igauniski skanošu vārda formu. Vārda diena tam ir 24. jūlijā kopā ar Kristiina, Krista, Kristin, Kristel, Kersti un citām šīs saimes formām.','Agrīnās svētās ar šo vārdu vairāk pazīstamas no leģendām nekā no dokumentiem, taču Kristīnai no Bolsenas ir arī arheoloģiskas pēdas. Katakombās pie Bolsenas Itālijas vidienē atrastas agrīnas kristiešu baznīcas paliekas un mocekles kaps; uzraksti liecina, ka viņas vārds bija līdzīgs «Christina» un ka viņu kā svēto godāja jau 4. gadsimta beigās. Svētā Kristīna ar mocekļa vainagu redzama arī jaunavu procesijā 6. gadsimta mozaīkā Sant’Apollināre Nuovo bazilikā Ravennā.'],
 lt:['Kristi — mažybinė Kristinos forma: anglų kalboje ji kilusi iš Christina ar Christine, estų — iš Kristiina. Pats Kristinos vardas kilęs iš lotynų Christiana, vardo Christianus — „krikščionis“ — moteriškosios formos. Estijoje Kristi laikoma estiškai skambančia vardo forma. Vardadienį ji švenčia liepos 24 dieną kartu su Kristiina, Krista, Kristin, Kristel, Kersti ir kitomis šios šeimos formomis.','Ankstyvosios šio vardo šventosios labiau žinomos iš legendų nei iš dokumentų, tačiau Kristina iš Bolsenos paliko ir archeologinį pėdsaką. Katakombose prie Bolsenos, centrinėje Italijoje, rasta ankstyvosios krikščionių bažnyčios liekanų ir kankinės kapas; užrašai rodo, kad ji vadinosi panašiai į „Christina“ ir jau IV amžiaus pabaigoje buvo gerbiama kaip šventoji. Šventoji Kristina su kankinės vainiku vaizduojama ir mergelių procesijoje VI amžiaus mozaikoje Sant’Apollinare Nuovo bazilikoje Ravenoje.'],
 et:['Kristi on Kristiina hellitusvorm: inglise keeles on see tekkinud nimedest Christina ja Christine, eesti keeles nimest Kristiina. Kristiina ise ulatub ladina nimeni Christiana, nime Christianus, „kristlane“, naissoost kujuni. Eestis peetakse Kristit eestipäraseks nimekujuks. Nimepäev on tal 24. juulil koos Kristiina, Krista, Kristini, Kristeli, Kersti ja teiste selle pere nimedega.','Selle nime varased pühakud on tuntud pigem legendidest kui dokumentidest, kuid Bolsena Kristiinast on jäänud ka arheoloogiline jälg. Kesk-Itaalias Bolsena katakombidest leiti varakristliku kiriku jäänused ja naismärtri haud; raidkirjad näitavad, et tema nimi oli umbes „Christina“ ning teda austati pühakuna juba 4. sajandi lõpuks. Märtrikroonis Kristiina on kujutatud ka neitsite rongkäigus Ravenna Sant’Apollinare Nuovo basiilika 6. sajandi mosaiigil.']
});
add('Merike',['https://www.behindthename.com/name/merike','https://fi.wikipedia.org/wiki/Merike','https://en.wikipedia.org/wiki/Julius_M%C3%A4giste'],{
 ru:['Merike — эстонское женское имя от слова meri — «море» с уменьшительным суффиксом, то есть примерно «морюшко». Финские справочники считают его параллельной формой имён Meri, Merika и Merikki и отмечают, что в эстонском произношении k звучит почти как долгий согласный — «Мерикке». Имя иногда дают и в Финляндии и Швеции. В эстонском календаре Merike празднует именины 22 апреля вместе с Meri.','Как личное имя Merike впервые предложил в 1929 году эстонский языковед Юлиус Мягисте. Он и сам носил созданную фамилию: родился в 1900 году в деревне Кассема под Тарту как Julius Gustavi Mälson и в 1922 году сменил фамилию на Mägiste. Мягисте преподавал в Тартуском университете, в 1934–1936 годах возглавлял Общество родного языка, в 1944 году бежал из Эстонии и до 1967 года преподавал финно-угорские языки в Лундском университете в Швеции.'],
 en:['Merike is an Estonian women’s name formed from meri, “sea”, with a diminutive suffix, roughly “little sea”. Finnish references treat it as a parallel form of Meri, Merika and Merikki and note that in Estonian pronunciation the k sounds almost like a long consonant, “Merikke”. The name is occasionally given in Finland and Sweden as well. In the Estonian calendar Merike shares its name day, 22 April, with Meri.','The linguist Julius Mägiste first proposed Merike as a given name in 1929. He himself bore a newly chosen surname: born in 1900 in the village of Kassema near Tartu as Julius Gustavi Mälson, he changed his name to Mägiste in 1922. Mägiste taught at the University of Tartu, led the Mother Tongue Society from 1934 to 1936, fled Estonia in 1944 and taught Finno-Ugric languages at Lund University in Sweden until 1967.'],
 lv:['Merike ir igauņu sieviešu vārds no vārda meri — «jūra» ar deminutīva piedēkli, aptuveni «jūriņa». Somu uzziņu avoti uzskata to par vārdu Meri, Merika un Merikki paralēlformu un norāda, ka igauņu izrunā k skan gandrīz kā garš līdzskanis — «Merikke». Vārdu reizēm dod arī Somijā un Zviedrijā. Igauņu kalendārā Merike vārda diena ir 22. aprīlī kopā ar Meri.','Kā personvārdu Merike pirmo reizi 1929. gadā ieteica igauņu valodnieks Jūliuss Mēgiste. Arī viņam pašam bija jauns, izvēlēts uzvārds: dzimis 1900. gadā Kasemas ciemā pie Tartu kā Julius Gustavi Mälson, viņš 1922. gadā mainīja uzvārdu uz Mägiste. Mēgiste mācīja Tartu Universitātē, no 1934. līdz 1936. gadam vadīja Dzimtās valodas biedrību, 1944. gadā bēga no Igaunijas un līdz 1967. gadam mācīja somugru valodas Lundas Universitātē Zviedrijā.'],
 lt:['Merike — estiškas moters vardas iš žodžio meri — „jūra“ su mažybine priesaga, maždaug „jūrelė“. Suomių žinynai jį laiko vardų Meri, Merika ir Merikki lygiagrečia forma ir pažymi, kad estiškai tariant k skamba beveik kaip ilgas priebalsis — „Merikke“. Vardas kartais duodamas ir Suomijoje bei Švedijoje. Estų kalendoriuje Merike vardadienį švenčia balandžio 22 dieną kartu su Meri.','Kaip asmenvardį Merike pirmą kartą 1929 metais pasiūlė estų kalbininkas Juliusas Mägiste. Ir jis pats turėjo naujai pasirinktą pavardę: gimęs 1900 metais Kassemos kaime netoli Tartu kaip Julius Gustavi Mälson, 1922 metais jis pavardę pakeitė į Mägiste. Mägiste dėstė Tartu universitete, 1934–1936 metais vadovavo Gimtosios kalbos draugijai, 1944 metais pabėgo iš Estijos ir iki 1967 metų dėstė finougrų kalbas Lundo universitete Švedijoje.'],
 et:['Merike on eesti naisenimi, mis on tuletatud sõnast meri deminutiivliitega. Soome käsiraamatud peavad seda nimede Meri, Merika ja Merikki rööpkujuks ning märgivad, et eesti hääldusena kõlab k peaaegu pika konsonandina, „Merikke“. Nime on aeg-ajalt pandud ka Soomes ja Rootsis. Eesti kalendris on Merikel ühine nimepäev Meriga, 22. aprill.','Eesnimeks pakkus Merike esimest korda välja keeleteadlane Julius Mägiste 1929. aastal. Temalgi oli ise valitud perekonnanimi: ta sündis 1900. aastal Tartumaal Kassema külas Julius Gustavi Mälsonina ja muutis 1922. aastal oma nime Mägisteks. Mägiste õpetas Tartu ülikoolis, juhtis aastatel 1934–1936 Emakeele Seltsi, põgenes 1944. aastal Eestist ning õpetas kuni 1967. aastani Rootsis Lundi ülikoolis soome-ugri keeli.']
});
add('Rasmus',['https://www.behindthename.com/name/rasmus','https://www.behindthename.com/name/erasmus','https://en.wikipedia.org/wiki/Erasmus_of_Formia','https://sv.wikipedia.org/wiki/Rasmus_p%C3%A5_luffen'],{
 ru:['Rasmus — скандинавская, финская и эстонская форма имени Эразм. Оно происходит от греческого erasmios — «любимый, желанный». Святой Эразм Формийский, известный также как святой Эльм, по преданию, погиб около 303 года; его почитают как покровителя моряков и одного из Четырнадцати святых помощников, хотя исторической основы у его жития, по всей видимости, нет. Позднее имя прославил нидерландский гуманист эпохи Возрождения Эразм Роттердамский.','Для многих читателей Расмус — прежде всего мальчик из книги Астрид Линдгрен «Rasmus på luffen» («Расмус-бродяга»), вышедшей в 1956 году; по-эстонски она называется «Hulkur Rasmus». Расмус живёт в детском доме и мечтает, чтобы его усыновили, но приезжие всегда выбирают кудрявых девочек, а не мальчика с прямыми волосами. Он убегает и отправляется в путь с беззаботным бродягой Парадиз-Оскаром. Книга выросла из радиопьесы, а первый фильм по этому сюжету вышел ещё в 1955 году.'],
 en:['Rasmus is the Scandinavian, Finnish and Estonian form of Erasmus, from Greek erasmios, “beloved, desired”. Saint Erasmus of Formia, also known as Saint Elmo, is said to have died around 303; he is venerated as the patron saint of sailors and as one of the Fourteen Holy Helpers, although his legend appears to have no historical basis. Later the name was made famous by the Dutch Renaissance scholar Erasmus of Rotterdam.','For many readers Rasmus is above all the boy in Astrid Lindgren’s Rasmus på luffen (Rasmus and the Vagabond), published in 1956 and known in Estonian as Hulkur Rasmus. Rasmus lives in an orphanage and longs to be adopted, but visitors always choose a curly-haired girl rather than a boy with straight hair. He runs away and takes to the road with the carefree tramp Paradis-Oskar. The book grew out of a radio play, and the first film of the story was released as early as 1955.'],
 lv:['Rasmus ir skandināvu, somu un igauņu vārda Erasms forma. Tas cēlies no grieķu erasmios — «mīļotais, vēlamais». Svētais Erasms no Formijas, saukts arī par svēto Elmu, pēc nostāsta miris ap 303. gadu; viņu godina kā jūrnieku aizbildni un vienu no Četrpadsmit svētajiem palīgiem, lai gan viņa leģendai, šķiet, nav vēsturiska pamata. Vēlāk vārdu padarīja slavenu Renesanses laika nīderlandiešu humānists Erasms Roterdamietis.','Daudziem lasītājiem Rasmus vispirms ir zēns no Astrīdas Lindgrēnes grāmatas «Rasmus på luffen» («Klaidonis Rasmus»), kas iznāca 1956. gadā; igauniski tā saucas «Hulkur Rasmus». Rasmus dzīvo bērnunamā un sapņo, ka viņu adoptēs, taču apmeklētāji vienmēr izvēlas meitenes ar cirtainiem matiem, nevis zēnu ar taisniem matiem. Viņš aizbēg un dodas ceļā kopā ar bezrūpīgo klaidoni Paradīzes Oskaru. Grāmata izauga no radioizrādes, un pirmā filma pēc šī stāsta iznāca jau 1955. gadā.'],
 lt:['Rasmus — skandinaviška, suomiška ir estiška Erazmo vardo forma. Jis kilęs iš graikų erasmios — „mylimas, geidžiamas“. Šv. Erazmas iš Formijos, dar vadinamas šv. Elmu, pasak padavimo, mirė apie 303 metus; jis gerbiamas kaip jūrininkų globėjas ir vienas iš Keturiolikos šventųjų pagalbininkų, nors jo legenda, regis, neturi istorinio pagrindo. Vėliau vardą išgarsino Renesanso epochos olandų humanistas Erazmas Roterdamietis.','Daugeliui skaitytojų Rasmus pirmiausia yra berniukas iš Astridos Lindgren knygos „Rasmus på luffen“ („Rasmusas valkata“), išleistos 1956 metais; estiškai ji vadinasi „Hulkur Rasmus“. Rasmusas gyvena vaikų namuose ir svajoja būti įvaikintas, tačiau lankytojai visada išsirenka garbanotą mergaitę, o ne tiesiaplaukį berniuką. Jis pabėga ir leidžiasi į kelionę su nerūpestingu valkata Paradis-Oskaru. Knyga išaugo iš radijo pjesės, o pirmasis filmas pagal šią istoriją pasirodė dar 1955 metais.'],
 et:['Rasmus on Erasmuse skandinaavia, soome ja eesti kuju. See tuleneb kreeka sõnast erasmios, „armastatud, ihaldatud“. Püha Erasmus Formiast, keda tuntakse ka püha Elmona, suri pärimuse järgi umbes aastal 303; teda austatakse meremeeste kaitsepühakuna ja ühena neljateistkümnest pühast abistajast, kuigi tema legendil ei paista olevat ajaloolist alust. Hiljem tegi nime kuulsaks renessansiaja Hollandi humanist Rotterdami Erasmus.','Paljudele lugejatele on Rasmus eelkõige poiss Astrid Lindgreni raamatust „Rasmus på luffen“, mis ilmus 1956. aastal ja on eesti keeles tuntud kui „Hulkur Rasmus“. Rasmus elab lastekodus ja loodab, et ta lapsendatakse, kuid külalised valivad alati pigem lokkis juustega tüdruku kui sirgete juustega poisi. Ta põgeneb ja asub teele koos muretu hulkuri Paradiisi-Oskariga. Raamat sündis kuuldemängust ning esimene film selle loo ainetel valmis juba 1955. aastal.']
});
add('Jaanus',['https://www.behindthename.com/name/jaanus','https://www.emakeeleselts.ee/omakeel/2011_2/OK_2011-2_03.pdf','https://et.wikipedia.org/wiki/Tasuja'],{
 ru:['Jaanus — вариант имени Jaan, то есть Иоанн. Языковед Хуно Рятсеп пишет, что эту форму эстонцы получили от нижненемецкого населения, а возникла она, вероятно, на основе имени Jan в средневековой латыни, где окончание -us было обычным, а на заднем плане могло звучать имя римского бога Януса. На это указывают похожие имена в других языках: польское Janusz, венгерское János, чешское Januš, финское Janus.','Рятсеп изучил Ляэнемааскую вакенбуху 1518 года — книгу повинностей крестьян 86 деревень Сааре-Ляэнеского епископства, составленную на латыни эстонцем Иоганном Пульком. В ней записаны имена около полутора тысяч крестьян, крещённых в основном во второй половине XV века, и чаще имени Ianus, которое встречается так же часто, как Peter, там записано только Mattis. Такое обилие Янусов в старых документах заметил и молодой Эдуард Борнхёэ: героя своей повести «Мститель» (1880) о восстании Юрьевой ночи он назвал Яанусом.'],
 en:['Jaanus is a variant of Jaan, that is, John. The linguist Huno Rätsep writes that Estonians took this form from the Low German population, and that it probably arose from Jan in medieval Latin, where the ending -us was typical, perhaps with the name of the Roman god Janus in the background. Similar names in other languages point the same way: Polish Janusz, Hungarian János, Czech Januš and Finnish Janus.','Rätsep studied the Läänemaa wackenbook of 1518, a register of peasant dues for 86 villages of the Bishopric of Ösel-Wiek, compiled in Latin by an Estonian named Johann Pulck. It lists about fifteen hundred peasants, most of them christened in the second half of the fifteenth century, and only Mattis occurs more often than Ianus, which is as frequent as Peter. The abundance of the name in old documents also caught the eye of the young Eduard Bornhöhe, who called the hero of his 1880 story Tasuja (“The Avenger”), about the St George’s Night Uprising, Jaanus.'],
 lv:['Jaanus ir vārda Jaan, tas ir, Jāņa, variants. Valodnieks Huno Retseps raksta, ka šo formu igauņi pārņēma no lejasvāciešiem un ka tā, visticamāk, radās no vārda Jan viduslaiku latīņu valodā, kur galotne -us bija ierasta, iespējams, ar romiešu dieva Jāņa (Janus) vārdu fonā. Uz to norāda līdzīgi vārdi citās valodās: poļu Janusz, ungāru János, čehu Januš un somu Janus.','Retseps izpētīja 1518. gada Lēnemā vakas grāmatu — Sāmsalas-Vīkas bīskapijas 86 ciemu zemnieku klaušu reģistru, ko latīņu valodā sastādīja igaunis Johans Pulks. Tajā ierakstīti ap pusotra tūkstoša zemnieku, galvenokārt kristītu 15. gadsimta otrajā pusē, un biežāk par vārdu Ianus, kas sastopams tikpat bieži kā Peter, tajā ierakstīts tikai Mattis. Vārda biežumu vecajos dokumentos pamanīja arī jaunais Eduards Bornhēe, kurš 1880. gada stāsta «Atriebējs» par Jura nakts sacelšanos varoni nosauca par Jānusu.'],
 lt:['Jaanus — vardo Jaan, t. y. Jono, variantas. Kalbininkas Huno Rätsepas rašo, kad šią formą estai perėmė iš žemutinių vokiečių, o ji greičiausiai atsirado iš vardo Jan viduramžių lotynų kalboje, kur galūnė -us buvo įprasta, galbūt su romėnų dievo Januso vardu fone. Tai rodo panašūs vardai kitose kalbose: lenkų Janusz, vengrų János, čekų Januš ir suomių Janus.','Rätsepas ištyrė 1518 metų Läänemaa vakų knygą — Saremos-Vykės vyskupijos 86 kaimų valstiečių prievolių registrą, kurį lotyniškai sudarė estas Johannas Pulckas. Joje įrašyta apie pusantro tūkstančio valstiečių, daugiausia pakrikštytų XV amžiaus antrojoje pusėje, ir dažniau už vardą Ianus, kuris pasitaiko taip pat dažnai kaip Peter, joje įrašytas tik Mattis. Vardo gausą senuose dokumentuose pastebėjo ir jaunasis Eduardas Bornhöhe, kuris savo 1880 metų apysakos „Keršytojas“ apie Jurginių nakties sukilimą herojų pavadino Jaanusu.'],
 et:['Jaanus on nime Jaan variant. Keeleteadlane Huno Rätsep kirjutab, et oleme Jaanuse saanud alamsakslastelt ning see nimekuju on arvatavasti sündinud Jani alusel keskaegses ladina keeles, kus -us oli tüüpiline nimelõpp ja taustal võis virvendada roomlaste jumala Januse nimi. Sellele viitavad sarnased nimed teisteski keeltes: poola Janusz, ungari János, tšehhi Januš ja soome Janus.','Rätsep uuris 1518. aasta Läänemaa vakuraamatut — Saare-Lääne piiskopkonna 86 küla talupoegade koormiste registrit, mille koostas ladina keeles eestlane Johann Pulck. Sinna on kirja pandud umbes poolteist tuhat talupoega, kes olid ristitud peamiselt 15. sajandi teisel poolel, ning Ianusest, mis esineb sama sageli kui Peter, on sagedasem ainult Mattis. Nime sagedus vanades ürikutes torkas silma ka noorele Eduard Bornhöhele, kes pani 1880. aastal ilmunud jüriöö ülestõusu ainelise jutustuse „Tasuja“ peategelase nimeks Jaanus.']
});
add('Siim',['https://www.behindthename.com/name/siim','https://www.behindthename.com/name/simon-1','https://www.emakeeleselts.ee/omakeel/2011_2/OK_2011-2_03.pdf','https://et.wikipedia.org/wiki/Simunap%C3%A4ev'],{
 ru:['Siim — эстонская форма имени Симон. Сначала это была краткая форма, но теперь имя живёт самостоятельно. Греческое Simon передаёт еврейское Шимон — «слушание», от глагола shamaʿ — «слышать». Имя пришло в Эстонию с католическими святцами задолго до Реформации: в Ляэнемааской вакенбухе 1518 года, где записаны крестьяне, крещённые в основном во второй половине XV века, Symon (Siim) входит в первую полутора десятка самых частых крестильных имён.','Именины Siim приходятся на 28 октября — simunapäev, день памяти апостолов Симона и Иуды Фаддея, названный по первому из них. В Южной Тартумаа, Вильяндимаа и Вырумаа этот день отмечал начало ледостава: с него ждали зимних дорог. Этим апостолам посвящена церковь Симуна в Эстонии, а в Средние века в таллинской церкви Святого Духа был их алтарь, а в Тартуском Домском соборе — капелла их имени.'],
 en:['Siim is the Estonian form of Simon. It began as a short form but is now used independently. Greek Simon renders Hebrew Shimʿon, “hearing, listening”, from shamaʿ, “to hear”. The name reached Estonia with the Catholic calendar of saints long before the Reformation: in the Läänemaa wackenbook of 1518, which lists peasants christened mostly in the second half of the fifteenth century, Symon (Siim) is among the fifteen most frequent baptismal names.','Siim has its name day on 28 October, simunapäev, the feast of the apostles Simon and Jude Thaddeus, named after the first of them. In southern Tartumaa, Viljandimaa and Võrumaa the day marked the beginning of the freeze, when people started to look forward to winter roads. The church at Simuna in Estonia is dedicated to these apostles, and in the Middle Ages the Church of the Holy Spirit in Tallinn had an altar of Simon and Jude, while Tartu Cathedral had a chapel of the same name.'],
 lv:['Siim ir igauņu vārda Sīmanis forma. Sākotnēji tā bija īsā forma, bet tagad vārdu lieto patstāvīgi. Grieķu Simon atveido ebreju Šimon — «klausīšanās», no darbības vārda shamaʿ — «dzirdēt». Vārds Igaunijā ienāca ar katoļu svēto kalendāru ilgi pirms reformācijas: 1518. gada Lēnemā vakas grāmatā, kurā ierakstīti galvenokārt 15. gadsimta otrajā pusē kristīti zemnieki, Symon (Siim) ir starp piecpadsmit biežākajiem kristību vārdiem.','Siim vārda diena ir 28. oktobrī — simunapäev, apustuļu Sīmaņa un Jūdas Tadeja piemiņas diena, kas nosaukta pēc pirmā no viņiem. Dienvidtartumā, Viljandimā un Võrumā šī diena iezīmēja aizsalšanas sākumu, kad sāka gaidīt ziemas ceļus. Šiem apustuļiem veltīta Simunas baznīca Igaunijā, bet viduslaikos Tallinas Svētā Gara baznīcā bija viņu altāris un Tartu Doma baznīcā — viņu vārdā nosaukta kapela.'],
 lt:['Siim — estiška Simono forma. Iš pradžių tai buvo trumpinys, bet dabar vardas vartojamas savarankiškai. Graikiškas Simon perteikia hebrajišką Šimon — „klausymas“, nuo veiksmažodžio shamaʿ — „girdėti“. Vardas į Estiją atėjo su katalikų šventųjų kalendoriumi gerokai prieš Reformaciją: 1518 metų Läänemaa vakų knygoje, kurioje įrašyti daugiausia XV amžiaus antrojoje pusėje pakrikštyti valstiečiai, Symon (Siim) yra tarp penkiolikos dažniausių krikšto vardų.','Siim vardadienis yra spalio 28 dieną — simunapäev, apaštalų Simono ir Judo Tado minėjimo diena, pavadinta pirmojo iš jų vardu. Pietų Tartumaa, Viljandimaa ir Võrumaa kraštuose ši diena žymėjo užšalimo pradžią, kai imta laukti žiemos kelių. Šiems apaštalams skirta Simunos bažnyčia Estijoje, o viduramžiais Talino Šventosios Dvasios bažnyčioje buvo jų altorius, o Tartu katedroje — jų vardo koplyčia.'],
 et:['Siim on Simoni eesti kuju. Algselt oli see lühivorm, kuid nüüd kasutatakse seda iseseisva nimena. Kreeka Simon annab edasi heebrea nime Šimon, „kuulmine“, mis tuleneb tegusõnast shamaʿ, „kuulma“. Nimi jõudis Eestisse katoliku pühakute kalendriga ammu enne reformatsiooni: 1518. aasta Läänemaa vakuraamatus, kuhu on kirja pandud peamiselt 15. sajandi teisel poolel ristitud talupojad, kuulub Symon (Siim) viieteistkümne sagedasema ristinime hulka.','Siimu nimepäev on 28. oktoobril, simunapäeval, mis on apostlite Siimona ja Juuda Taddeuse mälestuspäev ning on saanud nime neist esimese järgi. Lõuna-Tartumaal, Viljandimaal ja Võrumaal märkis see päev jäätumise algust ja talveteede ootust. Neile apostlitele on pühitsetud Simuna kirik ning keskajal oli Tallinna Püha Vaimu kirikus Siimoni ja Juuda altar ja Tartu toomkirikus samanimeline kabel.']
});
add('Raivo',['https://et.wikipedia.org/wiki/Raivo','https://www.behindthename.com/name/raivo','https://www.izpetnieks.lv/en/name/Raivo','https://en.wiktionary.org/wiki/Raivis'],{
 ru:['Происхождение имени Raivo не установлено. В Эстонии высказывались два объяснения: что это переделка имени Раймунд (Raimond) или что оно связано со словом raev — «ярость»; Behind the Name упоминает старое эстонское слово raivo с тем же значением. Справочник Nordic Names тоже приводит обе версии — эстонскую форму германского Raginmund и финское raivo — «ярость». Ни одна из них не доказана.','Интересна история имени в Латвии. Латышская база данных имён описывает Raivo как эстонское имя или имя неясного происхождения и относит самое раннее известное латышское упоминание к 1965 году. По словарю личных имён Клавса Силиньша, уже в 1966 году впервые записано и имя Raivis — латышскую переделку эстонского Raivo с привычным латышским окончанием. В латышском календаре Raivo празднует именины 29 мая вместе с Raivis, Raiva и Raivita, а в эстонском — 25 октября.'],
 en:['The origin of Raivo has not been established. In Estonia two explanations have been offered: that it is an adaptation of Raimund (Raimond), or that it is linked with the word raev, “rage”; Behind the Name mentions an Old Estonian word raivo with the same meaning. The Nordic Names reference likewise gives both options, an Estonian form of the Germanic Raginmund and Finnish raivo, “fury”. Neither has been proven.','The name has an interesting Latvian chapter. A Latvian name database describes Raivo as an Estonian name or one of undetermined origin and dates the earliest known Latvian record to 1965. According to Klāvs Siliņš’s dictionary of Latvian personal names, Raivis was first recorded in 1966, a Latvian version of the Estonian Raivo with a familiar Latvian ending. In the Latvian calendar Raivo celebrates on 29 May together with Raivis, Raiva and Raivita, and in the Estonian calendar on 25 October.'],
 lv:['Vārda Raivo izcelsme nav noskaidrota. Igaunijā izteikti divi skaidrojumi: ka tas ir pārveidots vārds Raimunds (Raimond) vai ka tas saistīts ar vārdu raev — «niknums»; Behind the Name min seno igauņu vārdu raivo ar tādu pašu nozīmi. Arī uzziņu avots Nordic Names min abas versijas — ģermāņu Raginmund igauņu formu un somu raivo — «trakums, niknums». Neviena no tām nav pierādīta.','Interesanta ir vārda vēsture Latvijā. Latviešu vārdu datubāze raksturo Raivo kā igauņu vārdu vai vārdu ar nenoteiktu izcelsmi, un agrākā zināmā latviešu liecība tajā ir no 1965. gada. Saskaņā ar Klāva Siliņa latviešu personvārdu vārdnīcu jau 1966. gadā pirmoreiz fiksēts arī vārds Raivis — igauņu Raivo latvisko variantu ar ierastu latviešu galotni. Latviešu kalendārā Raivo vārda diena ir 29. maijā kopā ar Raivis, Raiva un Raivita, bet igauņu kalendārā — 25. oktobrī.'],
 lt:['Vardo Raivo kilmė nenustatyta. Estijoje pateikti du paaiškinimai: kad tai pakeistas vardas Raimundas (Raimond) arba kad jis susijęs su žodžiu raev — „įniršis“; Behind the Name mini seną estų žodį raivo ta pačia reikšme. Žinynas Nordic Names taip pat pateikia abi versijas — germaniško Raginmund estišką formą ir suomių raivo — „įtūžis“. Nė viena jų neįrodyta.','Įdomi vardo istorija Latvijoje. Latvių vardų duomenų bazė Raivo apibūdina kaip estišką arba neaiškios kilmės vardą, o ankstyviausią žinomą latvišką paminėjimą nurodo 1965 metais. Pasak Klāvo Siliņio latvių asmenvardžių žodyno, jau 1966 metais pirmą kartą užfiksuotas ir Raivis — latvišką estiško Raivo variantą su įprasta latviška galūne. Latvių kalendoriuje Raivo vardadienis yra gegužės 29 dieną kartu su Raivis, Raiva ir Raivita, o estų kalendoriuje — spalio 25 dieną.'],
 et:['Nime Raivo päritolu pole kindlaks tehtud. Eestis on pakutud kaht seletust: et see on mugandus nimest Raimund (Raimond) või et sellel on seos sõnaga raev; Behind the Name mainib sama tähendusega vana eesti sõna raivo. Ka Nordic Namesi andmestik toob mõlemad võimalused — germaani nime Raginmund eesti kuju ja soome sõna raivo, „raev“. Kumbagi pole tõestatud.','Huvitav on nime lugu Lätis. Läti nimede andmebaas kirjeldab Raivot kui eesti või määramata päritoluga nime ning varaseim teadaolev Läti märge pärineb seal 1965. aastast. Klāvs Siliņši läti isikunimede sõnaraamatu järgi on juba 1966. aastal esimest korda kirja pandud ka nimi Raivis — eesti Raivo lätipärase kuju tavalise läti lõpuga. Läti kalendris on Raivo nimepäev 29. mail koos Raivise, Raiva ja Raivitaga, Eesti kalendris aga 25. oktoobril.']
});
add('Niina',['https://et.wikipedia.org/wiki/Niina','https://www.behindthename.com/name/niina','https://www.behindthename.com/name/nina-1','https://en.wikipedia.org/wiki/Saint_Nino'],{
 ru:['Niina — эстонская форма русского имени Нина; эстонская Википедия называет его именем русского происхождения. Behind the Name считает Niina финской и эстонской формой имени Nina, а в финском языке — ещё и краткой формой имени Anniina. Само имя Нина, по его данным, возникло как сокращение имён на -нина, например Антонина, и в XIX веке распространилось в Западной Европе из России и Италии. В эстонском календаре Niina празднует именины 28 ноября.','В православном мире самая известная святая с этим именем — Нино, которую называют также святой Ниной, просветительница Грузии. По большинству преданий она была из грекоязычной семьи из Каппадокии. Святая Нино пришла в Иберийское царство с крестом из виноградной лозы, полученным в видении от Богородицы, исцеляла больных и обратила царицу Нану. Царь Мириан III, заблудившись на охоте, нашёл дорогу лишь после молитвы «Богу Нино» и около 326 года объявил христианство государственной религией.'],
 en:['Niina is the Estonian form of the Russian name Nina, and Estonian Wikipedia describes it as a name of Russian origin. Behind the Name treats Niina as a Finnish and Estonian form of Nina, and in Finnish also as a short form of Anniina. According to the same source, Nina began as a short form of names ending in -nina, such as Antonina, and spread to Western Europe from Russia and Italy in the nineteenth century. In the Estonian calendar Niina has its name day on 28 November.','In the Orthodox world the best-known saint of this name is Nino, also called Saint Nina, who brought Christianity to Georgia. Most traditions say that she came from a Greek-speaking family in Cappadocia. Nino arrived in the Kingdom of Iberia with a grapevine cross received in a vision of the Virgin Mary, healed the sick and converted Queen Nana. King Mirian III, lost in darkness on a hunting trip, found his way only after praying to “Nino’s God”, and around 326 he declared Christianity the official religion of his kingdom.'],
 lv:['Niina ir krievu vārda Ņina igauņu forma; igauņu Vikipēdija to sauc par krievu izcelsmes vārdu. Behind the Name uzskata Niina par vārda Nina somu un igauņu formu, bet somu valodā arī par vārda Anniina īso formu. Pats vārds Nina, pēc tā paša avota, radies kā saīsinājums vārdiem ar galotni -nina, piemēram, Antonina, un 19. gadsimtā izplatījās Rietumeiropā no Krievijas un Itālijas. Igauņu kalendārā Niina vārda diena ir 28. novembrī.','Pareizticīgo pasaulē pazīstamākā svētā ar šo vārdu ir Nino, saukta arī par svēto Ņinu, Gruzijas apgaismotāja. Pēc vairuma nostāstu viņa nākusi no grieķu valodā runājošas ģimenes Kapadokijā. Nino ieradās Ibērijas valstī ar vīnogulāja krustu, ko vīzijā saņēma no Dievmātes, dziedināja slimos un atgrieza ticībā karalieni Nanu. Karalis Mirians III, apmaldījies medībās, atrada ceļu tikai pēc lūgšanas «Nino Dievam» un ap 326. gadu pasludināja kristietību par valsts reliģiju.'],
 lt:['Niina — estiška rusiško vardo Nina forma; estiškoji Vikipedija jį vadina rusų kilmės vardu. Behind the Name laiko Niina suomiška ir estiška vardo Nina forma, o suomių kalboje — ir vardo Anniina trumpiniu. Pats vardas Nina, pasak to paties šaltinio, atsirado kaip vardų, besibaigiančių -nina, pavyzdžiui, Antonina, trumpinys ir XIX amžiuje iš Rusijos ir Italijos paplito Vakarų Europoje. Estų kalendoriuje Niina vardadienis yra lapkričio 28 dieną.','Stačiatikių pasaulyje garsiausia šio vardo šventoji yra Nino, dar vadinama šventąja Nina, Gruzijos apšvietėja. Pasak daugumos padavimų, ji kilo iš graikiškai kalbančios šeimos Kapadokijoje. Nino atvyko į Iberijos karalystę su vynmedžio kryžiumi, kurį regėjime gavo iš Dievo Motinos, gydė ligonius ir atvertė karalienę Naną. Karalius Mirianas III, paklydęs medžioklėje, rado kelią tik pasimeldęs „Nino Dievui“ ir apie 326 metus paskelbė krikščionybę valstybine religija.'],
 et:['Niina on vene nime Nina eesti kuju ning Eesti Vikipeedia nimetab seda venepäraseks nimeks. Behind the Name peab Niinat nime Nina soome ja eesti kujuks, soome keeles ka nime Anniina lühivormiks. Sama allika järgi tekkis Nina -nina-lõpuliste nimede, näiteks Antonina lühendina ning levis 19. sajandil Venemaalt ja Itaaliast Lääne-Euroopasse. Eesti kalendris on Niina nimepäev 28. novembril.','Õigeusu maailmas on selle nime tuntuim pühak Gruusia valgustaja Nino, keda nimetatakse ka pühaks Ninaks. Enamiku pärimuste järgi pärines ta Kapadookiast kreeka keelt kõnelevast perest. Nino saabus Ibeeria kuningriiki viinapuust ristiga, mille ta oli nägemuses saanud Neitsi Maarjalt, ravis haigeid ja pööras usku kuninganna Nana. Jahil pimedusse eksinud kuningas Mirian III leidis tee alles pärast palvet „Nino Jumalale“ ning kuulutas umbes aastal 326 ristiusu oma riigi ametlikuks usuks.']
});
add('Maie',['https://et.wikipedia.org/wiki/Maie','https://www.behindthename.com/name/maie','https://www.behindthename.com/name/maia-3','https://www.emakeeleselts.ee/wp-content/uploads/2021/12/Hergauk-Mald.pdf'],{
 ru:['Maie — эстонское женское имя, вариант имени Maia, которое Behind the Name считает эстонской формой имени Мария; к тому же кругу относятся Mall, Malle, Mare и Maris. Справочник Nordic Names называет Maie вариантом имени Maja. В эстонском календаре Maie празднует именины 2 мая вместе с Mai, Maia и Maiu.','Для нескольких поколений эстонцев Maie — имя из букваря. Лиина Хергаук и Ингрид Мальд изучили эстонские буквари и учебники математики разных эпох и выяснили, что в букварях 1940–1985 годов самым частым женским именем было Maie: оно встретилось в пяти букварях. За ним шли Anna, Anne, Ene, Lilli, Liina, Imbi и Leelo. Места действия в этих букварях вообще не назывались: всё происходило просто в деревне, в лесу, на кухне, на рынке, в саду или в школе.'],
 en:['Maie is an Estonian women’s name, a variant of Maia, which Behind the Name identifies as an Estonian form of Maria; Mall, Malle, Mare and Maris belong to the same circle. The Nordic Names reference describes Maie as a variant of Maja. In the Estonian calendar Maie celebrates its name day on 2 May together with Mai, Maia and Maiu.','For several generations of Estonians Maie was a name from the primer. Liina Hergauk and Ingrid Mald studied Estonian primers and mathematics textbooks from different periods and found that in primers from 1940 to 1985 the most frequent women’s name was Maie, which appeared in five primers, followed by Anna, Anne, Ene, Lilli, Liina, Imbi and Leelo. Those primers named no places at all: everything simply happened in the countryside, in the forest, in the kitchen, at the market, in the garden or at school.'],
 lv:['Maie ir igauņu sieviešu vārds, vārda Maia variants; Behind the Name Maia uzskata par Marijas igauņu formu, un tajā pašā lokā ir Mall, Malle, Mare un Maris. Uzziņu avots Nordic Names sauc Maie par vārda Maja variantu. Igauņu kalendārā Maie vārda diena ir 2. maijā kopā ar Mai, Maia un Maiu.','Vairākām igauņu paaudzēm Maie ir vārds no ābeces. Līna Hergauka un Ingrīda Malda pētīja dažādu laikmetu igauņu ābeces un matemātikas grāmatas un atklāja, ka 1940.–1985. gada ābecēs biežākais sieviešu vārds bija Maie, kas parādījās piecās ābecēs; tam sekoja Anna, Anne, Ene, Lilli, Liina, Imbi un Leelo. Šajās ābecēs vietvārdu nebija nemaz: viss notika vienkārši laukos, mežā, virtuvē, tirgū, dārzā vai skolā.'],
 lt:['Maie — estiškas moters vardas, vardo Maia variantas; Behind the Name Maia laiko estiška Marijos forma, o tam pačiam ratui priklauso Mall, Malle, Mare ir Maris. Žinynas Nordic Names Maie vadina vardo Maja variantu. Estų kalendoriuje Maie vardadienį švenčia gegužės 2 dieną kartu su Mai, Maia ir Maiu.','Kelioms estų kartoms Maie — vardas iš elementoriaus. Liina Hergauk ir Ingrid Mald tyrė įvairių laikotarpių estų elementorius ir matematikos vadovėlius ir nustatė, kad 1940–1985 metų elementoriuose dažniausias moters vardas buvo Maie, pasirodęs penkiuose elementoriuose; po jo ėjo Anna, Anne, Ene, Lilli, Liina, Imbi ir Leelo. Tuose elementoriuose vietovardžių iš viso nebuvo: viskas vyko tiesiog kaime, miške, virtuvėje, turguje, sode ar mokykloje.'],
 et:['Maie on eesti naisenimi, nime Maia variant; Behind the Name peab Maiat Maria eesti kujuks ning samasse ringi kuuluvad Mall, Malle, Mare ja Maris. Nordic Namesi andmestik nimetab Maiet nime Maja variandiks. Eesti kalendris on Maie nimepäev 2. mail koos Mai, Maia ja Maiuga.','Mitmele eestlaste põlvkonnale on Maie aabitsanimi. Liina Hergauk ja Ingrid Mald uurisid eri ajastute eesti aabitsaid ja matemaatikaõpikuid ning leidsid, et aastate 1940–1985 aabitsates oli populaarseim naisenimi Maie, mis esines viies aabitsas; sellele järgnesid Anna, Anne, Ene, Lilli, Liina, Imbi ja Leelo. Kohanimesid nendes aabitsates üldse polnud: tegevus toimus lihtsalt maal, metsas, köögis, turul, aias või koolis.']
});
add('Triin',['https://www.behindthename.com/name/triin','https://et.wikipedia.org/wiki/Triin_(eesnimi)','https://et.wikipedia.org/wiki/Kadrip%C3%A4ev'],{
 ru:['Triin — эстонская уменьшительная форма имени Katariina, то есть Екатерина; от того же имени происходят Kadri, Kaisa и Katrin. В эстонском календаре Triin, Triina и Triinu празднуют именины 25 ноября — в kadripäev, день святой Екатерины Александрийской. Так имя оказалось связано с одним из самых живых праздников эстонского народного календаря.','День святой Екатерины закрепился за 25 ноября примерно в X веке, а в Эстонии kadripäev сложился в XVI веке, когда обряды древнего «времени душ» и посвящения девушек смешались с христианским праздником. Его считали женским днём: к этому времени женщины заканчивали осенние работы со скотом. Девушки ходили по домам ряжеными kadrisandid в чистых белых одеждах — их связывают с молоком, которое, по легенде, текло из тела святой вместо крови. В этот день стригли овец, а пословица говорила: «Март — над землёй, Кадри — над стадом».'],
 en:['Triin is an Estonian diminutive of Katariina, Katherine; Kadri, Kaisa and Katrin come from the same name. In the Estonian calendar Triin, Triina and Triinu share their name day on 25 November, kadripäev, the feast of Saint Catherine of Alexandria. In this way the name is tied to one of the liveliest days of the Estonian folk calendar.','St Catherine’s feast became fixed on 25 November around the tenth century, and in Estonia kadripäev took shape in the sixteenth century, when rituals of the old season of the souls and of girls’ initiation merged with the Christian feast. It was regarded as a women’s day, because by then women had finished their outdoor autumn work with the cattle. Girls went from house to house as kadrisandid, mummers dressed in clean white clothes, which are linked with the milk that, according to legend, flowed from the saint’s body instead of blood. Sheep were shorn that day, and a proverb said: “Mart is over the land, Kadri over the herd.”'],
 lv:['Triin ir igauņu vārda Katariina, tas ir, Katrīnas, deminutīvs; no tā paša vārda cēlušies arī Kadri, Kaisa un Katrin. Igauņu kalendārā Triin, Triina un Triinu vārda diena ir 25. novembrī — kadripäev, svētās Katrīnas Aleksandrietes dienā. Tā vārds ir saistīts ar vienu no dzīvīgākajām igauņu tautas kalendāra dienām.','Svētās Katrīnas diena nostiprinājās 25. novembrī ap 10. gadsimtu, bet Igaunijā kadripäev izveidojās 16. gadsimtā, kad senā «dvēseļu laika» un meiteņu iesvētību rituāli saplūda ar kristīgo svētku dienu. To uzskatīja par sieviešu svētkiem, jo līdz tam laikam sievietes pabeidza rudens darbus ar lopiem ārā. Meitenes staigāja pa mājām kā kadrisandid — maskās, tīrās baltās drēbēs, ko saista ar pienu, kas pēc leģendas svētās nāves brīdī tecējis asiņu vietā. Šajā dienā cirpa aitas, un sakāmvārds teica: «Mārtiņš pār zemi, Kadri pār ganāmpulku.»'],
 lt:['Triin — estiška mažybinė vardo Katariina, t. y. Kotrynos, forma; iš to paties vardo kilę ir Kadri, Kaisa bei Katrin. Estų kalendoriuje Triin, Triina ir Triinu vardadienį švenčia lapkričio 25 dieną — kadripäev, šv. Kotrynos Aleksandrietės dieną. Taip vardas susietas su viena gyviausių estų liaudies kalendoriaus švenčių.','Šv. Kotrynos šventė lapkričio 25 dieną įsitvirtino apie X amžių, o Estijoje kadripäev susiformavo XVI amžiuje, kai senojo „vėlių meto“ ir mergaičių įšventinimo apeigos susiliejo su krikščioniška švente. Ji laikyta moterų diena, nes iki to laiko moterys baigdavo rudens darbus su gyvuliais lauke. Mergaitės vaikščiojo po namus kaip kadrisandid — persirengėlės švariais baltais drabužiais, kurie siejami su pienu, pasak legendos, tekėjusiu iš šventosios kūno vietoj kraujo. Tą dieną kirpdavo avis, o patarlė sakė: „Martynas — virš žemės, Kadri — virš bandos.“'],
 et:['Triin on Katariina eesti hellitusvorm; samast nimest pärinevad ka Kadri, Kaisa ja Katrin. Eesti kalendris peavad Triin, Triina ja Triinu nimepäeva 25. novembril, kadripäeval, Aleksandria püha Katariina mälestuspäeval. Nii on nimi seotud eesti rahvakalendri ühe elavama tähtpäevaga.','Püha Katariina mälestuspäev kinnistus 25. novembrile umbes 10. sajandil, Eestis aga kujunes kadripäev 16. sajandil, kui muinasaegse usundi hingedeaja rituaalid ja tütarlaste initsiatsiooniriitused segunesid kristliku pühaga. Seda peeti naistepühaks, sest selleks ajaks lõpetasid naised karjakasvatusega seotud välised sügistööd. Tüdrukud käisid kadrisantideks puhastes valgetes riietes, mida seostatakse piimaga — legendi järgi voolas pühaku hukkamisel tema kehast vere asemel piim. Sel päeval pügati lambaid ja vanasõna ütles: „Mart on üle maa, Kadri üle karja.“']
});
add('Tiit',['https://et.wikipedia.org/wiki/Tiit','https://www.behindthename.com/name/tiit','https://www.behindthename.com/name/theodoric','https://en.wikipedia.org/wiki/Tiit_Kuusik'],{
 ru:['Tiit — эстонское мужское имя, первоначально краткая форма старинного эстонского имени Tiidrik, а теперь самостоятельное. Tiidrik восходит к древневерхненемецкой форме имени Теодорих, а оно — к готскому Þiudareiks, «правитель народа», из слов þiuda — «народ» и reiks — «правитель, король». В эстонском календаре Tiit празднует именины 18 сентября вместе с Tiidrik, Tiido и Tiidu.','Связь эстонского Tiit с немецким Dietrich хорошо видна в биографии оперного певца Тийта Куузика. Он родился 24 сентября 1911 года в Пярну и при рождении получил имя Dietrich Kuusik. В июне 1938 года баритон получил первую премию на международном конкурсе вокалистов в Вене, исполнив каватину Фигаро, а затем более сорока лет был ведущим солистом театра «Эстония». На премьере оперы Эугена Каппа «Tasuleegid» в 1945 году он пел партию Вамбо.'],
 en:['Tiit is an Estonian men’s name, originally a short form of the old Estonian name Tiidrik and now used independently. Tiidrik goes back to the Old High German form of Theodoric, which in turn comes from Gothic Þiudareiks, “ruler of the people”, from þiuda, “people”, and reiks, “ruler, king”. In the Estonian calendar Tiit has its name day on 18 September together with Tiidrik, Tiido and Tiidu.','The link between Estonian Tiit and German Dietrich shows clearly in the life of the opera singer Tiit Kuusik. He was born in Pärnu on 24 September 1911 as Dietrich Kuusik. In June 1938 the baritone won first prize at an international singing competition in Vienna with Figaro’s cavatina, and he went on to be a principal soloist of the Estonia Theatre for more than four decades. At the 1945 premiere of Eugen Kapp’s opera Tasuleegid he sang the role of Vambo.'],
 lv:['Tiit ir igauņu vīriešu vārds, sākotnēji sena igauņu vārda Tiidrik īsā forma, bet tagad patstāvīgs vārds. Tiidrik cēlies no Teodoriha senaugšvācu formas, kas savukārt nāk no gotu Þiudareiks — «tautas valdnieks», no þiuda — «tauta» un reiks — «valdnieks, karalis». Igauņu kalendārā Tiit vārda diena ir 18. septembrī kopā ar Tiidrik, Tiido un Tiidu.','Igauņu Tiit saikne ar vācu Dietrich labi redzama operdziedātāja Tīta Kūsika biogrāfijā. Viņš dzimis 1911. gada 24. septembrī Pērnavā kā Dietrich Kuusik. 1938. gada jūnijā baritons ar Figaro kavatīnu ieguva pirmo prēmiju starptautiskā dziedātāju konkursā Vīnē un pēc tam vairāk nekā četrus gadu desmitus bija viens no teātra «Estonia» galvenajiem solistiem. Eižena Kapa operas «Tasuleegid» pirmizrādē 1945. gadā viņš dziedāja Vambo lomu.'],
 lt:['Tiit — estiškas vyriškas vardas, iš pradžių seno estiško vardo Tiidrik trumpinys, o dabar savarankiškas vardas. Tiidrik kilęs iš senosios aukštaičių vokiečių Teodoriko formos, o ši — iš gotų Þiudareiks, „tautos valdovas“, iš þiuda — „tauta“ ir reiks — „valdovas, karalius“. Estų kalendoriuje Tiit vardadienį švenčia rugsėjo 18 dieną kartu su Tiidrik, Tiido ir Tiidu.','Estiško Tiit ryšys su vokišku Dietrich gerai matyti operos dainininko Tiito Kuusiko biografijoje. Jis gimė 1911 metų rugsėjo 24 dieną Pärnu ir gimdamas gavo vardą Dietrich Kuusik. 1938 metų birželį baritonas su Figaro kavatina laimėjo pirmąją premiją tarptautiniame dainininkų konkurse Vienoje, o vėliau daugiau kaip keturis dešimtmečius buvo vienas pagrindinių teatro „Estonia“ solistų. Eugeno Kappo operos „Tasuleegid“ premjeroje 1945 metais jis dainavo Vambo partiją.'],
 et:['Tiit on eesti mehenimi, algselt vana eesti nime Tiidrik lühivariant, nüüd iseseisev nimi. Tiidrik pärineb vanaülemsaksa nimest Theodoric, mis omakorda ulatub gooti nimeni Þiudareiks, „rahva valitseja“, sõnadest þiuda, „rahvas“, ja reiks, „valitseja, kuningas“. Eesti kalendris on Tiidul nimepäev 18. septembril koos Tiidriku, Tiido ja Tiiduga.','Eesti Tiidu ja saksa Dietrichi seos tuleb hästi esile ooperilaulja Tiit Kuusiku eluloos. Ta sündis 24. septembril 1911 Pärnus ja sai sündides nimeks Dietrich Kuusik. 1938. aasta juunis võitis bariton Figaro kavatiiniga Viinis rahvusvahelise lauljate konkursi esimese auhinna ning oli seejärel üle nelja aastakümne Estonia teatri juhtivaid soliste. Eugen Kapi ooperi „Tasuleegid“ esietendusel 1945. aastal laulis ta Vambo osa.']
});
add('Tõnu',['https://et.wikipedia.org/wiki/T%C3%B5nu','https://et.wikipedia.org/wiki/T%C3%B5nis','https://et.wikipedia.org/wiki/T%C3%B5nisep%C3%A4ev'],{
 ru:['Tõnu — эстонское мужское имя, возникшее как сокращение имени Tõnis, а Tõnis, в свою очередь, происходит от латинского Antonius, то есть Антоний. В эстонском календаре Tõnu празднует именины 17 января вместе с Tõnis, Tõnn и Tõnno. Этот день, tõnisepäev, — один из старых праздников эстонского народного календаря.','Tõnisepäev получил название ещё в католические времена — по дню памяти монаха Антония Великого, который католическая церковь отмечает 17 января; в народном календаре дата сместилась, когда Эстония в 1918 году перешла на григорианский календарь. В Эстонии этот день веками связывали с жертвами домашнему духу и с заботой о свиньях: святой Антоний считался их покровителем, а его почитание переплелось с культом домового духа Тынна. День считали серединой зимы: к нему должна была остаться половина корма для скота, а прясть в этот день запрещалось.'],
 en:['Tõnu is an Estonian men’s name that arose as a shortening of Tõnis, and Tõnis in turn comes from Latin Antonius, Anthony. In the Estonian calendar Tõnu has its name day on 17 January together with Tõnis, Tõnn and Tõnno. That day, tõnisepäev, is one of the old feasts of the Estonian folk calendar.','Tõnisepäev was named in Catholic times after the memorial day of the monk Anthony the Great, which the Catholic Church keeps on 17 January; the date in the folk calendar shifted when Estonia adopted the Gregorian calendar in 1918. Over the centuries the day became linked in Estonia with offerings to the household spirit and with luck for the pigs: Saint Anthony was regarded as their protector, and his tradition intertwined with the cult of the household spirit Tõnn. The day was thought to halve the winter, so half of the animals’ fodder should still be left, and spinning was forbidden.'],
 lv:['Tõnu ir igauņu vīriešu vārds, kas radies, saīsinot vārdu Tõnis, bet Tõnis savukārt cēlies no latīņu Antonius — Antonijs. Igauņu kalendārā Tõnu vārda diena ir 17. janvārī kopā ar Tõnis, Tõnn un Tõnno. Šī diena, tõnisepäev, ir viena no senajām igauņu tautas kalendāra svētku dienām.','Tõnisepäev nosaukumu ieguva vēl katoļu laikos — pēc mūka Antonija Lielā piemiņas dienas, ko katoļu baznīca svin 17. janvārī; tautas kalendārā datums pārbīdījās, kad Igaunija 1918. gadā pārgāja uz Gregora kalendāru. Gadsimtu gaitā šo dienu Igaunijā saistīja ar upuriem mājas garam un cūku labklājību: svēto Antoniju uzskatīja par cūku aizstāvi, un viņa godināšana savijās ar mājas gara Tõnn kultu. Dienu uzskatīja par ziemas vidu — līdz tai bija jāpaliek pusei lopbarības, un vērpt šajā dienā nedrīkstēja.'],
 lt:['Tõnu — estiškas vyriškas vardas, atsiradęs sutrumpinus vardą Tõnis, o Tõnis savo ruožtu kilęs iš lotyniško Antonius — Antanas. Estų kalendoriuje Tõnu vardadienį švenčia sausio 17 dieną kartu su Tõnis, Tõnn ir Tõnno. Ši diena, tõnisepäev, yra viena senųjų estų liaudies kalendoriaus švenčių.','Tõnisepäev pavadinimą gavo dar katalikiškais laikais — pagal vienuolio šv. Antano Didžiojo minėjimo dieną, kurią Katalikų Bažnyčia švenčia sausio 17-ąją; liaudies kalendoriuje data pasislinko, kai Estija 1918 metais perėjo prie Grigaliaus kalendoriaus. Per šimtmečius ši diena Estijoje susieta su aukomis namų dvasiai ir kiaulių sėkme: šv. Antanas laikytas kiaulių globėju, o jo tradicija susipynė su namų dvasios Tõnno kultu. Diena laikyta žiemos viduriu — iki jos turėjo likti pusė pašaro, o verpti tą dieną buvo draudžiama.'],
 et:['Tõnu on eesti mehenimi, mis on saadud Tõnise lühendamisel, Tõnis aga on tuletatud ladina nimest Antonius. Eesti kalendris on Tõnul nimepäev 17. jaanuaril koos Tõnise, Tõnni ja Tõnnoga. See päev, tõnisepäev, on üks eesti rahvakalendri vanu tähtpäevi.','Tõnisepäev sai nime katoliku aegadel kristliku munga Antonios Suure mälestuspäeva järgi, mida katoliku kirik tähistab 17. jaanuaril; rahvakalendris nihkus päev koos Gregoriuse kalendri kasutuselevõtuga 1918. aastal. Sajandite jooksul ühendati tõnisepäeva Eestis koduhaldjale ohverdamise ja sigadeõnne tagamisega: püha Antonius oli sigade kaitsja ning temast lähtuv pärimus põimus koduhaldja Tõnni kultusega. Päeva peeti talve poolitajaks — loomasöödast pidi siis pool alles olema — ning sel päeval ei tohtinud kedrata.']
});
add('Kersti',['https://www.behindthename.com/name/kersti','https://www.behindthename.com/name/kerstin','https://et.wikipedia.org/wiki/Kersti_Merilaas','https://en.wikipedia.org/wiki/Kersti_Merilaas'],{
 ru:['Kersti — вариант шведского имени Kerstin, то есть шведской формы имени Кристина. Кристина восходит к латинскому Christiana, женской форме от Christianus — «христианин». Kersti есть и в эстонском, и в латышском календаре: в обоих именины приходятся на 24 июля, в один день с Кристиной и её многочисленными формами.','Одна из самых известных носительниц имени выбрала его сама. Эстонская поэтесса Керсти Мерилаас родилась 7 декабря 1913 года в Нарве как Евгения (Eugenie) Моорберг; раннее детство до 1917 года она провела в Петербурге. Под именем Kersti Merilaas она писала стихи, книги для детей и пьесы и занималась переводом, а с 1936 года по документам звалась Kersti Sang — по фамилии мужа, Аугуста Санга. Её первый сборник «Maantee tuuled» вышел в 1938 году.'],
 en:['Kersti is a variant of Swedish Kerstin, the Swedish form of Christina. Christina goes back to Latin Christiana, the feminine of Christianus, “a Christian”. Kersti appears in both the Estonian and the Latvian calendars, and in both it has its name day on 24 July, the same day as Christina and her many forms.','One of the best-known bearers chose the name herself. The Estonian poet Kersti Merilaas was born in Narva on 7 December 1913 as Eugenie Moorberg and spent her early childhood, until 1917, in St Petersburg. As Kersti Merilaas she wrote poetry, children’s books and plays and worked as a translator, and from 1936 her civil name was Kersti Sang, taking the surname of her husband, August Sang. Her first collection, Maantee tuuled, appeared in 1938.'],
 lv:['Kersti ir zviedru vārda Kerstin variants; Kerstin ir Kristīnas zviedru forma. Kristīna cēlusies no latīņu Christiana, vārda Christianus — «kristietis» — sieviešu formas. Kersti ir gan igauņu, gan latviešu kalendārā, un abos tā vārda diena ir 24. jūlijā, vienā dienā ar Kristīnu un daudzajām tās formām.','Viena no pazīstamākajām šī vārda nesējām to izvēlējās pati. Igauņu dzejniece Kersti Merilāsa dzimusi Narvā 1913. gada 7. decembrī kā Eugenie Moorberg un agro bērnību līdz 1917. gadam pavadīja Pēterburgā. Kā Kersti Merilaas viņa rakstīja dzeju, bērnu grāmatas un lugas un tulkoja, bet no 1936. gada viņas oficiālais vārds bija Kersti Sang — ar vīra Augusta Sanga uzvārdu. Viņas pirmais krājums «Maantee tuuled» iznāca 1938. gadā.'],
 lt:['Kersti — švediško vardo Kerstin variantas; Kerstin yra švediška Kristinos forma. Kristina kilusi iš lotynų Christiana, vardo Christianus — „krikščionis“ — moteriškosios formos. Kersti yra ir estų, ir latvių kalendoriuose, ir abiejuose jos vardadienis yra liepos 24 dieną, tą pačią dieną kaip Kristinos ir daugybės jos formų.','Viena žinomiausių šio vardo nešiotojų jį pasirinko pati. Estų poetė Kersti Merilaas gimė Narvoje 1913 metų gruodžio 7 dieną kaip Eugenie Moorberg, o ankstyvąją vaikystę iki 1917 metų praleido Peterburge. Kersti Merilaas vardu ji rašė eilėraščius, knygas vaikams bei pjeses ir vertė, o nuo 1936 metų jos oficialus vardas buvo Kersti Sang — su vyro Augusto Sango pavarde. Pirmasis jos rinkinys „Maantee tuuled“ išėjo 1938 metais.'],
 et:['Kersti on rootsi nime Kerstin variant; Kerstin on Kristiina rootsi kuju. Kristiina ulatub ladina nimeni Christiana, nime Christianus, „kristlane“, naissoost kujuni. Kersti on nii Eesti kui ka Läti kalendris ning mõlemas on tema nimepäev 24. juulil, samal päeval Kristiina ja selle paljude kujudega.','Üks tuntumaid nime kandjaid valis selle endale ise. Luuletaja Kersti Merilaas sündis 7. detsembril 1913 Narvas Eugenie Moorbergina ning veetis varajase lapsepõlve kuni 1917. aastani Peterburis. Kersti Merilaasina kirjutas ta luulet, lasteraamatuid ja näidendeid ning tõlkis, aastast 1936 oli tema kodanikunimi Kersti Sang — abikaasa August Sangi perekonnanimega. Tema esimene luulekogu „Maantee tuuled“ ilmus 1938. aastal.']
});
add('Merle',['https://et.wikipedia.org/wiki/Merle','https://www.behindthename.com/name/merle','https://www.nordicnames.de/wiki/Merle_f'],{
 ru:['Merle — эстонское женское имя неизвестного происхождения. В других языках у этого слова есть свои значения: английское merle и французская фамилия Merle означают «чёрный дрозд» (от латинского merula), а справочник Nordic Names упоминает ещё и южнонемецкую и идишскую ласковую форму имени Мария. Behind the Name подчёркивает, что связь эстонского имени с английским неясна. В эстонском календаре Merle празднует именины 29 декабря вместе с Merli и Merili.','История имени в Эстонии необычна. Широко Merle начало распространяться примерно с 1955 года, хотя его не было ни в одном из рекомендательных списков имён и ни в одном календаре соседних народов. Значит, к эстонским родителям оно пришло не через именники и не через церковный календарь. Behind the Name, рассказывая о западном Merle, вспоминает коварную героиню романа Генри Джеймса «Женский портрет» (1880) — мадам Мерль, хотя там Merle — фамилия.'],
 en:['Merle is an Estonian women’s name of unknown origin. In other languages the word has meanings of its own: English merle and the French surname Merle both mean “blackbird” (from Latin merula), and the Nordic Names reference also mentions a South German and Yiddish pet form of Maria. Behind the Name stresses that a connection between the Estonian name and the English one is uncertain. In the Estonian calendar Merle has its name day on 29 December together with Merli and Merili.','The name’s Estonian history is unusual. Merle began to spread widely from about 1955, although it appeared in none of the recommended name lists and in none of the name calendars of neighbouring nations. So it did not reach Estonian parents through name books or a church calendar. In its account of the western name, Behind the Name recalls the devious Madame Merle in Henry James’s novel The Portrait of a Lady (1880), although there Merle is in fact a surname.'],
 lv:['Merle ir igauņu sieviešu vārds ar nezināmu izcelsmi. Citās valodās šim vārdam ir savas nozīmes: angļu merle un franču uzvārds Merle nozīmē «melnais strazds» (no latīņu merula), bet uzziņu avots Nordic Names min arī dienvidvācu un jidiša Marijas mīlināmo formu. Behind the Name uzsver, ka igauņu vārda saikne ar angļu vārdu nav skaidra. Igauņu kalendārā Merle vārda diena ir 29. decembrī kopā ar Merli un Merili.','Vārda vēsture Igaunijā ir neparasta. Plaši Merle sāka izplatīties ap 1955. gadu, lai gan tā nebija nevienā ieteicamo vārdu sarakstā un nevienā kaimiņtautu vārdu kalendārā. Tātad pie igauņu vecākiem tas nonāca nevis caur vārdu grāmatām vai baznīcas kalendāru. Stāstot par rietumu vārdu Merle, Behind the Name atgādina viltīgo madame Merlu Henrija Džeimsa romānā «Kādas dāmas portrets» (1880), lai gan tur Merle patiesībā ir uzvārds.'],
 lt:['Merle — nežinomos kilmės estiškas moters vardas. Kitose kalbose šis žodis turi savų reikšmių: angliškas merle ir prancūziška pavardė Merle reiškia „juodasis strazdas“ (iš lotynų merula), o žinynas Nordic Names mini ir pietų vokiečių bei jidiš meilią Marijos formą. Behind the Name pabrėžia, kad estiško vardo ryšys su anglišku neaiškus. Estų kalendoriuje Merle vardadienį švenčia gruodžio 29 dieną kartu su Merli ir Merili.','Vardo istorija Estijoje neįprasta. Plačiai Merle ėmė plisti maždaug nuo 1955 metų, nors jo nebuvo nė viename rekomenduojamų vardų sąraše ir nė viename kaimyninių tautų vardų kalendoriuje. Vadinasi, pas estų tėvus jis atkeliavo ne per vardynus ar bažnytinį kalendorių. Pasakodamas apie vakarietišką Merle, Behind the Name primena klastingą madam Merl Henry Jameso romane „Ponios portretas“ (1880), nors ten Merle iš tikrųjų yra pavardė.'],
 et:['Merle on tundmatu algupäraga eesti naisenimi. Teistes keeltes on sel sõnal oma tähendused: inglise merle ja prantsuse perekonnanimi Merle tähendavad musträstast (ladina merula), Nordic Namesi andmestik mainib ka Maria lõunasaksa ja jidiši hellitusvormi. Behind the Name rõhutab, et eesti nime seos inglise nimega on ebakindel. Eesti kalendris on Merle nimepäev 29. detsembril koos Merli ja Meriliga.','Nime lugu Eestis on omapärane. Laialdasemalt hakkas Merle levima umbes 1955. aastast, kuigi see puudus kõigis soovitusnimestikes ja kõigis naaberrahvaste nimekalendrites. Seega ei jõudnud see eesti vanemateni nimeraamatute ega kirikukalendri kaudu. Läänemaise Merle puhul meenutab Behind the Name salakavalat madame Merle’i Henry Jamesi romaanis „Daami portree“ (1880), kuigi seal on Merle tegelikult perekonnanimi.']
});
